using namespace std;

vector<string> make_board(int n, char c1, char c2) {
	int w = 100;
	string s(w, c2);
	vector<string> board;
	board.emplace_back(s);

	while (n > 0) {
		auto t = s;
		for (int i = 0; i < w; i += 2) {
			t[i] = c1;
			n--;
			if (n == 0) {
				break;
			}
		}
		board.emplace_back(t);
		board.emplace_back(s);
	}
	board.emplace_back(s);
	return board;
}

