string ads(){
  string res;
  rep(i, 60){
    if((i/3) % 2 == 0) res.push_back('.');
    else res.push_back('#');
  }
  return res;
}

void f1(int a, int b){
  a -= 10; b -= 10;
  vector<string> ans;
  ans.push_back(ads());
  while(a != 0 || b != 0){
    ans.push_back(ads());
    auto now = &ans.back();
    for(int i = 1; i < now->size() && b > 0; i += 6){
      now->at(i) = '#';
      b--;
    }
    for(int i = 4; i < now->size() && a > 0;  i+= 6){
      now->at(i) = '.';
      a--;
    }
    ans.push_back(ads());
  }
  cout << ans.size() << " 60" << endl;
  for(string s : ans){
    cout << s << endl;
  }
}

void f2(int a, int b){
  vector<string> a1(2, string(18, '#'));
  vector<string> b1(2, string(18, '.'));
  a--; b--;
  for(int i = 0; i < 18 && a > 0; i += 2){
    a1.at(0).at(i) = '.';
    a--;
  }
  for(int i = 0; i < 18 && b > 0; i += 2){
    b1.at(1).at(i) = '#';
    b--;
  }
  cout << "4 18" << endl;
  for(string s : a1) cout << s << endl;
  for(string s : b1) cout << s << endl;
}

string mks(char x, char y, int co){
  string res;
  rep(i, 6*co-3){
    if((i/3) % 2 == 0) res.push_back(x);
    else res.push_back(y);
  }
  for(int i = res.size(); i < 100; i++) res.push_back(res.at(i-1));
  return res;
}

void f3(int a, int b){
  char x, y;
  if(a < b){
    x = '.', y = '#';
  }else{
    x = '#', y = '.';
    swap(a, b);
  }
  vector<string> ans;
  int sz = min(a, b);
  ans.push_back(mks(x, y, sz));
  a -= a; b -= a-1;
  while(b != 0){
    ans.push_back(mks(x, y, sz));
    auto &now = ans.back();
    for(int i = 1; i < now.size() && b != 0; i += 6){
      now.at(i) = y;
      b--;
    }
    ans.push_back(mks(x, y, sz));
  }
  cout << ans.size() << " " << ans.front().size() << endl;
  for(string s : ans){
    cout << s << endl;
  }
}

int main(){
  int a, b;
  cin >> a >> b;
  if(a >= 10 && b >= 10){
    f1(a, b);
  }else if(a < 10 && b < 10){
    f2(a, b);
  }else{
    f3(a, b);
  }
  return 0;
}

