int main(){

    int A, B;
    cin >> A >> B;
    string allWhite = "";
    string allBlack = "";
    string wb = "";
    for(int i = 0; i < 100; i++){
        allWhite += ".";
        allBlack += "#";
        if(i % 2 == 0){
            wb += ".";
        }
        else{
            wb += "#";
        }
    }

    A--;
    B--;
    vector<string> ans(100);
    int line = 0;
    ans[line] = allBlack;
    line++;
    while(A > 0){
        string temp = wb;
        if(A >= 50){
            A -= 50;
        }
        else{
            for(int i = 0; i < 100; i += 2){
                temp[i] = '#';
                A++;
                if(A == 50){
                    A = 0;
                    break;
                }
            }
        }
        ans[line] = temp;
        line++;
        ans[line] = allBlack;
        line++;
    }

    ans[line] = allWhite;
    line++;
    while(B > 0){
        string temp = wb;
        if(B >= 50){
            B -= 50;
        }
        else{
            for(int i = 1; i < 100; i += 2){
                temp[i] = '.';
                B++;
                if(B == 50){
                    B = 0;
                    break;
                }
            }
        }
        ans[line] = temp;
        line++;
        ans[line] = allWhite;
        line++;
    }

    cout << line << " " << 100 << "\n";
    for(int i = 0; i < line; i++){
        cout << ans[i] << "\n";
    }

    return 0;
}

