const int MAX_H = 100;
char grid[100][100];

void divide(int a){
    int c = min(a-1, MAX_H/4);
    for(int i=0;i<c;i++)
        for(int j=0;j<MAX_H;j++) grid[4*i+3][j] = '#';

    if (c==a-1) return;

    a -= c + 1;
    for(int i=0;i<MAX_H/4 && a;i++){
        if(c<a){
            for(int j=0;j<MAX_H;j++) grid[j][4*i+3] = '#';
            a -= c + 1;
        }else{
            for(int j=0;j<4*a;j++) grid[j][4*i+3] = '#';
            a = 0;
        }
    }
}

int main(){
    int a, b; cin >> a >> b;

    for(int i=0;i<MAX_H;i++){
        for(int j=0;j<MAX_H;j++) grid[i][j] = '.';
    }
    divide(a);

    if(a!=1) b--; 

    for(int i=1;i<MAX_H;i+=4){
        for(int j=1;j<MAX_H;j+=4)
            if(0<b--) grid[i][j] = '#';
    }

    cout << MAX_H << ' ' << MAX_H << endl;
    for(int i=0;i<MAX_H;i++){
        for(int j=0;j<MAX_H;j++) cout << grid[i][j] << ' ';
