const int maxn = 101;
char grid[maxn][maxn];
int h = 100, w = 100;
void solve(int white, int black){
    for(int e = 1; e <= h; e++) for(int f = 1; f <= w; f++) grid[e][f] = '.';
    for(int e = 1; e <= w; e++) if(e%2){
        if(black){
            grid[1][e] = '#';
            black--;
        }
    }
    grid[2][1] = '#';
    for(int f = 1; f <= w - 10; f++) grid[3][f] = '#';
    white--;
    for(int e = 3; e <= h; e += 2) for(int f = 1; f <= w - 10; f += 2){
        if(white){
            grid[e+1][f+1] = '#';
            grid[e+2][f] = '#';
            grid[e+2][f+1] = '#';
            white--;
        }
    }
}
int p[maxn * maxn];
void init(){
    for(int e = 1; e <= maxn * maxn; e++) p[e] = e;
}
int find(int x){
    if(x == p[x]) return x;
    return p[x] = find(p[x]);
}
int mh(int a, int b){
    return find(a * w + b);
}
int sum[maxn][maxn];
int main(){
    int a, b;
    cin >> a >> b;
    if(a > b){
        solve(b, a);
        for(int e = 1; e <= h; e++) for(int f = 1; f <= w; f++)
            if(grid[e][f] == '#') grid[e][f] = '.';
            else grid[e][f] = '#';
    } else {
        solve(a, b);
    }
    init();
    for(int e = 1; e <= h; e++) for(int f = 1; f <= w; f++){
        if(grid[e-1][f] == grid[e][f]) p[mh(e - 1, f)] = mh(e, f);
        if(grid[e+1][f] == grid[e][f]) p[mh(e + 1, f)] = mh(e, f);
        if(grid[e][f-1] == grid[e][f]) p[mh(e, f - 1)] = mh(e, f);
        if(grid[e][f+1] == grid[e][f]) p[mh(e, f + 1)] = mh(e, f);
    }
    int whi = 0, bla = 0;
    for(int e = 1; e <= h; e++) for(int f = 1; f <= w; f++){
        if(e * w + f == mh(e, f)) {
            if(grid[e][f] == '.') whi++;
            else bla++;
        }
    }
    // cerr << whi << " " << bla << endl;
    assert(whi == a);
    assert(bla == b);
    cout << h << " " << w << endl;
    for(int e = 1; e <= h; e++, cout << endl) for(int f = 1; f <= w; f++) cout << grid[e][f];
    return 0;
}

