#include <bits/stdc++.h>
using namespace std;
const int dh[8] = {0, 1, 0, -1, -1, 1, 1, -1};
const int dw[8] = {1, 0, -1, 0, 1, 1, -1, -1};
const char white = '.';
const char black = '#';
const int k = 50;
const int idx = 4;

vector<string> solve(int a, int b) {
    vector<string> s(2*k, string(2*k, black));
    for (int i = k; i < 2*k; i++) fill(s[i].begin(), s[i].end(), white);

    int pa = 0, pb = 0;
    for (int i = 0; i < k-1; i++) {
        for (int j = 0; j < 2*k; j++) {
            bool ok = true;
            for (int id = 0; id < idx; id++) {
                int di = i + dh[id], dj = j + dw[id];
                if (di < 0 || 2*k <= di) continue;
                if (dj < 0 || 2*k <= dj) continue;
                if (s[di][dj] == white) ok = false;
            }
            if (ok) { s[i][j] = white; pa++; }
            if (pa == a-1) break;
        }
        if (pa == a-1) break;
    }

    for (int i = 2*k-1; i > k; i--) {
        for (int j = 0; j < 2*k; j++) {
            bool ok = true;
            for (int id = 0; id < idx; id++) {
                int di = i + dh[id], dj = j + dw[id];
                if (di < 0 || 2*k <= di) continue;
                if (dj < 0 || 2*k <= dj) continue;
                if (s[di][dj] == black) ok = false;
            }
            if (ok) { s[i][j] = black; pb++; }
            if (pb == b-1) break;
        }
        if (pb == b-1) break;
    }
    return s;
}

int main() {
    int a, b;
    cin >> a >> b;
    vector<string> ans = solve(a, b);
    for (auto& v : ans) cout << v << endl;
    return 0;
}

