using namespace std;

typedef long long ll;
bool LTE(double a,double b) { return equals(a,b) || a < b; }
bool LT(double a,double b) { return !equals(a,b) && a < b; }

string s[100];
int dx[] = {1,0,-1,0};
int dy[] = {0,1,0,-1};

bool used[100][100];

void dfs(int x,int y,char c) {
  rep(k,4) {
    int nx = x + dx[k];
    int ny = y + dy[k];
    if( !( 0 <= nx && nx < 100 && 0 <= ny && ny < 100 ) ) continue;
    if( s[ny][nx] == c ) {
      if( used[ny][nx] ) continue;
      used[ny][nx] = true;
      dfs(nx,ny,c);
    }
  }
}

bool veri(int A,int B) {
  int a=0,b=0;
  rep(i,100) {
    rep(j,100) {
      if( !used[i][j] ) {
	used[i][j] = true;
	dfs(j,i,s[i][j]);
	if( s[i][j] == '.' ) ++a;
	else ++b;
      }
    }
  }
  return A == a && B == b;
}

bool check(int x,int y,char c) {
  rep(k,4) {
    int nx = x + dx[k];
    int ny = y + dy[k];
    if( !( 0 <= nx && nx < 100 && 0 <= ny && ny < 100 ) ) continue;
    if( s[ny][nx] == c ) return false;
  }
  return true;
}


void compute(int A,int B) {
  int pA = A, pB = B;
  rep(i,100) {
    if( i < 50 ) {
      s[i] = string(100,'.');
    } else {
      s[i] = string(100,'#');
    }
  }
  --A, --B;
  while( A > 0 ) {
    for(int y=99;y>=50;y-=2) {
      for(int x=99;x>=0;--x) {
	if( check(x,y,'.') ) {
	  s[y][x] = '.';
	  --A;
	  if( A <= 0 ) goto Skip;
	}
      }
    }
  Skip:;
  }
  while( B > 0 ) {
    for(int y=0;y<50;y+=2) {
      rep(x,100){
	if( check(x,y,'#') ) {
	  s[y][x] = '#';
	  --B;
	  if( B <= 0 ) goto Skip2;
	}
      }
    }
  Skip2:;
  }


  puts("100 100");
  rep(i,100) cout << s[i] << endl;
  assert( veri(pA,pB) );
}

