  while (b > 1) {
    grid[N - 1 - (1 + (b_counter / fill) * 2)][N - 1 - (2 + (b_counter % fill) * 2)] = '#';
    b--;
    b_counter++;    
  }
  cout << 100 << ' ' << 100 << endl;
  for (int i = 0; i < N; i++) {
    cout << grid[i] << endl;
  }
