    }
    for(j=98+i%2;j>=0 && B<0;j-=2){
      C[i-1][j]=d,B++;
      if(i==1 && j==99)
        B--;
      if(i!=1 && j!=0 && j!=99)
        B++;
    }
  }else if(B>0){
    i++;
    for(;B>0;i+=2){
      for(int j=0;j<100 && B>0;j+=2)
        C[i][j]=d,B--;
    }
  }
  for(int i=0;i<100;i++){
    for(int j=0;j<100;j++)
      cout<<C[i][j];
