int getcol(int x, int y) {
	if (x < 1 || x > MAX - 1) return -1;
	if (y < 1 || y > MAX - 1) return -1;
	return ans[x][y];
}

void buildwhite() {
	while (a) {
		for(int i = 51; i < MAX; i += 2) {
			fj(1, MAX - 1) {
				if (getcol(i, j) == 0) continue;
				bool f = true;
				fo(0, 3) {
					int x = i + dx[o];
					int y = j + dy[o];
					if (getcol(x, y) == 0) f = false;
				}
				if (f) {
					a--;
					ans[i][j] = 0;
					if (a == 0) return;
				}
			}
		}
	}
}

void buildblack() {
	while (b) {
		for(int i = 1; i < 50; i += 2) {
			fj(1, MAX - 1) {
				if (getcol(i, j) == 1) continue;
				bool f = true;
				fo(0, 3) {
					int x = i + dx[o];
					int y = j + dy[o];
					if (getcol(x, y) == 1) f = false;
				}
				if (f) {
					b--;
					ans[i][j] = 1;
					if (b == 0) return;
				}
			}
		}
	}
}


