bool check_field[101][101];
// A : .
// B : #

int main(int argc, char* argv[]){
  cin >> A >> B;
  bool lessWhite;
  int dif;
  int equal;
  if(A<=B){
	lessWhite = true;
	dif = B-A;
	equal = A;
  }else{
	lessWhite = false;
	dif = A-B;
	equal = B;
  }
  for(int i = 0; i < 100; i++)
	for(int j = 0; j < 100; j++)
	  check_field[i][j] = false;
  int rowCount = 0;
  int setCount = 0;
  int difCount = 0;
  int spRow, spCol;
  bool lastAdd = false;
  while(1){
	for(int i = 0; i < 100; i+=2){
	  if(check_field[rowCount][i])continue;
	  if(setCount<equal){
		if(rowCount%2==0){
		  field[rowCount][i] = (lessWhite?true:false);
		  field[rowCount][i+1] = (lessWhite?false:true);
		  check_field[rowCount][i] = check_field[rowCount][i+1] = true;
		}else{
		  field[rowCount][i] = ((!lessWhite)?true:false);
		  field[rowCount][i+1] = ((!lessWhite)?false:true);
		  check_field[rowCount][i] = check_field[rowCount][i+1] = true;
		}
		setCount++;
		if(setCount==equal){
		  lastAdd = true;
		  spRow = rowCount+1;
		  spCol = i+1;
		}
	  }else if(difCount<dif){
		if(rowCount%2==0){
		  field[rowCount][i] = (lessWhite?true:false);
		  field[rowCount][i+1] = (lessWhite?false:true);
		  field[rowCount+1][i] = (lessWhite?true:false);
		  field[rowCount+1][i+1] = (lessWhite?true:false);
		  check_field[rowCount][i] = check_field[rowCount][i+1] = true;
		  check_field[rowCount+1][i] = check_field[rowCount+1][i+1] = true;
		}else{
		  field[rowCount][i] = ((!lessWhite)?true:false);
		  field[rowCount][i+1] = ((!lessWhite)?false:true);
		  field[rowCount+1][i] = ((!lessWhite)?true:false);
		  field[rowCount+1][i+1] = ((!lessWhite)?true:false);
		  check_field[rowCount][i] = check_field[rowCount][i+1] = true;
		  check_field[rowCount+1][i] = check_field[rowCount+1][i+1] = true;
		}
		difCount++;
	  }else{
		if(lastAdd){
		  if(rowCount%2==0){
			field[rowCount][i] = (lessWhite?true:false);
			field[rowCount][i+1] = (lessWhite?true:false);
		  }else{
			field[rowCount][i] = ((!lessWhite)?true:false);
