void solv()
{
	int A, B; scanf("%d%d", &A, &B);
	const int h = 100, w = 100;
	int table[h][w];

	for (int i = 0; i < h / 2; i++){
		fill(table[i], table[i] + w, 0);
	}
	for (int i = h / 2; i < h; i++){
		fill(table[i], table[i] + w, 1);
	}

	A--; B--;

	int x = 0, y = 0;
	for (int i = 0; i < A; i++){
		table[x][y] = 1;
		y += 2;
		if (y >= w){
			x += 2;
			y = 0;
		}
	}
	x = h / 2 + 1; y = 0;
	for (int i = 0; i < B; i++){
		table[x][y] = 0;
		y += 2;
		if (y >= w){
			x += 2;
			y = 0;
		}
	}

	printf("%d %d\n", h, w);
	for (int i = 0; i < h; i++){
		for (int j = 0; j < w; j++){
			if (0 == table[i][j]){
				printf("#");
			}
			else{
				printf(".");
			}
		}
		printf("\n");
	}

	return;
}

