	cout << "100 100" << endl;
	bool white;
	vector<vector<bool>> ans(100, vector<bool>(100, false));
	ans[0][0] = true;
	A--; B--;

	if (A > B) {
		white = false;
		A += B;
		B = A - B;
		A = A - B;
	}
	else
		white = true;

	// A <= B である
	int c = 0, d = 0;
	while(A) {
		ans[c + 1][d + 1] = true;
		ans[c + 1][d + 2] = true;
		ans[c + 1][d + 3] = true;
		ans[c + 2][d + 1] = true;
		ans[c + 2][d + 3] = true;
		ans[c + 3][d + 1] = true;
		ans[c + 3][d + 2] = true;
		ans[c + 3][d + 3] = true;
		c += 4;
		if (c == 100) {
			c = 0;
			d += 4;
		}
		A--; B--;
	}
	while (B > 1) {
		ans[c + 1][d + 1] = true;
		ans[c + 1][d + 3] = true;
		c += 2;
		if (c == 100) {
			c = 0;
			d += 4;
		}
		B -= 2;
	}
	if (B) {
		ans[c + 1][d + 1] = true;
	}
	for (int i = 0;i < 100;i++) {
		for (int j = 0;j < 100;j++) {
			if (ans[i][j] == white)
				cout << '.';
			else
