using namespace std;

vector<string> make_board(int n, char c1, char c2) {
	int w = 100;
	string s(w, c2);
	vector<string> board;
	board.emplace_back(s);

	while (n > 0) {
		auto t = s;
		for (int i = 0; i < w; i += 2) {
			t[i] = c1;
			n--;
			if (n == 0) {
				break;
			}
		}
		board.emplace_back(t);
		board.emplace_back(s);
	}
	board.emplace_back(s);
	return board;
}

int main() {
	int a, b; // wthie, black
	cin >> a >> b;
	char c_a = '.';
	char c_b = '#';

	int w = 10;
	vector<string> board = make_board(a - 1, c_a, c_b);
	auto adding = make_board(b - 1, c_b, c_a);

	for (auto s: adding) {
		board.emplace_back(s);
	}


	cout << board.size() << endl;
	cout << board[0].size() << endl;
	for (auto sss: board) {
		cout << sss << endl;
	}
	return 0;
}

