    {
        cout << "1 2" << endl;
        cout << "#." << endl;
        return 0;
    }
    vector<vector<char>> map(100, vector<char>(100, '.'));
    ll blackCount = B;
    ll whiteCount = A;
    ll blockCount = 0;
    ll hidariueH = 0;
    ll hidariueW = 0;
    while (blockCount < whiteCount - 1)
    {
        map.at(hidariueH + 1).at(hidariueW) = '#';
        map.at(hidariueH).at(hidariueW + 1) = '#';
        map.at(hidariueH + 1).at(hidariueW + 1) = '#';
        hidariueW += 2;
        blockCount++;
        if (hidariueW == 100)
        {
            hidariueH += 2;
            hidariueW = 0;
        }
    }
    if(blockCount > 0)
    {
        blackCount--;
    }
    blockCount = 0;
    ll blackH = 99;
    ll blackW = 0;
    while (blockCount < blackCount)
    {
        map.at(blackH).at(blackW) = '#';
        blackW += 2;
        if (blackW == 100)
        {
            blackH -= 2;
            blackW = 0;
        }
        blockCount++;
    }
    cout << "100 100\n";
    for (int i = 0; i < 100; i++)
    {
        for (int j = 0; j < 100; j++)
        {
            cout << map.at(i).at(j);
        }
        cout << "\n";
    }
    cout.flush();
    return 0;
}

