template <typename T>
class segment_base{
	int N;//要素数
	vector< T > dat1;
	T VAL_E;//初期値
	T VAL_NULL;//空の値
public:
	segment_base(){};
	segment_base(int n,T val_E ):N(n),VAL_E(val_E){
		dat1.resize(2*n);
		dat1.assign(2*n,val_E);//初期化
	}
	void init(int n,T val_E,T val_N){
		N = n;
		VAL_E = val_E;
		VAL_NULL = val_N;
		int size = 2;
		while(size<N){
			size<<1;
		}
		N = size;
		dat1.resize(2*N);
		dat1.assign(2*N,val_E);
	}
	T SELECT(T& L,T& R){//扱う演算子
		T ans;
		ans = min(L,R);//
		return ans;
	}

	//index番目の値をvalに変更,indexは"0-index"
	void update(int i,T& val){
		i += N-1;
		dat1[i] = val;
		while(i>0){
			i = (i-1)/2;
			dat1[i] = SELECT(dat1[i*2+1],dat1[i*2+2]);
		}
	}

	//区間[L,R)のSELECT
	/*
	調べている範囲[a,b),階数k,見る場所[L,R)
	*/
	T query(int a,int b,int k,int L,int R){
		if( R<=a || b<=L ){
			return VAL_E;//交差しない
		}
		if( a<=L && R<=b && dat1[k] != VAL_NULL ){
			return dat1[k];
		}

		T res = VAL_E;
		int mid = (L+R)/2;
		if( a < mid ) res = SELECT(res,query(a,b,k*2+1,L,mid) );
		if( mid < b ) res = SELECT(res,query(a,b,k*2+2,mid,R) );
		return res;
	}
	T query(int L,int R){
		return query(L,R,0,0,N);
	}
};
