    else ch1 = '#', ch2 = '.', left = a;
    while(rows)
    {
        row++;
        for(int j = 1; j <= 100; j++) c[row][j] = ch1; 
        row++;
        c[row][1] = ch1;
        c[row][100] = ch1;
