        c[row][100] = ch1;
        for(int j = 3; j < 100; j += 2) if(left) {left--; c[row][j] = ch2;}
        row++;
        for(int j = 1; j <= 100; j++) c[row][j] = ch1; 
        rows -= 2;
    }
    for(int i = 1; i <= row; i++) for(int j = 1; j <= 100; j++) if(c[i][j] == '-') c[i][j] = ch1;
}

