void solve(ll A, ll B) {
    int N = 99;
    char c[100][100] = {};
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (i % 2 == 0) {
                c[i][j] = '#';
            } else {
                c[i][j] = '.';
            }
        }
    }
    for (int i = 0; i < N; i++)
        c[i][N - 1] = '#';
    for (int i = 1; i < N - 1; i++)
        c[i][0] = '.';


    A -= 1;
    B -= 1;
    for (int i = 1; i < N; i += 2) {
        for (int j = 2; j < N - 1; j += 2) {
            if (A == 0) break;
            c[i][j] = '#';
            A--;
        }
    }
    for (int i = N - 3; i >= 2; i -= 2) {
        for (int j = N - 2; j >= 2; j -= 2) {
            if (B == 0) break;
            c[i][j] = '.';
            B--;
        }
    }

    cout << N << " " << N << endl;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cout << c[i][j];
        }
        cout << endl;
    }
}


