        dbg("wrong A", a, cc);
        return false;
    }
    memset(u, false, sizeof u);
    FOR(i, MAXN) {
        FOR(j, MAXN) {
            if (f[i][j] == '#') {
                f[i][j] = '.';
            } else {
                f[i][j] = '#';
            }
        }
