        f[i] = tmp;
    }
    FOR(i, MAXN) {
        f[i][MAXN-1] = '#';
    }
    --a;
    for (int row = 3; a && row < MAXN-1; row += 4, a--) {
        FOR(i, MAXN) {
            f[row][i] = '#';
        }
    }
    while (a) {
        for (int col = 3; a && col < MAXN-1; col += 4) {
            for (int row = 0; a && row < MAXN-1; row += 4) {
                int to_row = min(row + 3, MAXN);
                for (int j = row; j <= to_row; ++j) {
                    f[j][col] = '#';
                }
                --a;
            }
        }
    }
    --b;

    for (int r = 1; b && r < MAXN-1; r += 4) {
        for (int c = 1; b && c < MAXN-1; c += 4, --b) {
            f[r][c] = '#';
        }
