using namespace std;
typedef long long ll;

int main(void) {
  ll A, B;
  cin >> A >> B;

  if(A == 1 && B == 1) {
    cout << 1 << " " << 2 << endl;
    cout << ".#" << endl;
    return 0;
  }

  bool rev = false;
  if(A > B) {
    swap(A, B);
    rev = true;
  }

  const ll H = 100, W = 100;
  char S[H][W];
  REP(i, 0, H) REP(j, 0, W) S[i][j] = '#';

  ll w = 0, b = 1;
  ll y = 0, x = 1;
  while(w + 1 < A) {
    S[y][x] = '.';
    w++;
    if(y > 0) b++;
    if(x == 0) {
      x = y + 2;
      y = 0;
    } else {
      y += 1;
      x -= 1;
    }
  }
  ll py = 99, px = 99;
  while(b < B) {
    S[py - 1][px - 1] = '.';
    S[py - 1][px] = '.';
    S[py][px - 1] = '.';
    b++;
    py -= 2;
    if(py < 0) {
      py = 99;
      px -= 2;
    }
  }

  if(rev) {
    REP(i, 0, H) REP(j, 0, W) {
      if(S[i][j] == '.') S[i][j] = '#';
      if(S[i][j] == '#') S[i][j] = '.';
    }
  }

  // cerr << w << " " << b << endl;
  cout << H << " " << W << endl;
  REP(i, 0, H) {
    REP(j, 0, W) cout << S[i][j];
    cout << endl;
  }
}

