#define int ll

void solve() {
	int N = 100;
	vector<vector<int>> field(N, vector<int>(N));
	int A, B; cin >> A >> B;
	--A; --B;
	REP(i, N / 2) REP(j, N) field[i][j] = 0;
	REP(i, N / 4) {
		REP(j, N / 2) {
			if(A-- > 0) field[i * 2][j * 2] = 1; // white
		}
	}

	std::reverse(ALL(field));
	REP(i, N / 2) REP(j, N) field[i][j] = 1;
	REP(i, N / 4) {
		REP(j, N / 2) {
			if(B-- > 0) field[i * 2][j * 2] = 0; // white
		}
	}

	cout << 100 << " " << 100 << endl;
	REP(i, N) {
		REP(j, N) cout << (field[i][j] == 1 ? '.' : '#');
		cout << endl;
	}
}

