int main(){
	cin>>A>>B;
	if (A>B){
		swap(A,B);
		sf=true;
	}
	{
		int b=B-A+1;
		REP(i,(b+49)/50*2){
			REP(j,100){
				ans[i][j]='.';
			}
		}
		REP(i,b){
			ans[i/50*2][(i%50)*2]='#';
		}
		h=(b+49)/50*2;
		A--;
	}
	if(A==0){
		show();
	}else{
		REP(i,25){
			if (i<A){
				ans[h][i*4]='.';
				REP(j,3){
					ans[h][i*4+j+1]='#';
				}
				REP(j,2){
					ans[h+1][i*4+j*2]='.';
					ans[h+1][i*4+j*2+1]='#';
				}
			}else{
				REP(j,2)REP(k,4){
					ans[h+j][i*4+k]='.';
				}
			}
		}
		A-=min(A,25);
		h+=2;
		if(A==0){
			show();
		}else{
			bool f=true;
			while(A){
				REP(i,50){
					if (i<A){
						if (f){
							ans[h][i*2]='#';
							ans[h][i*2+1]='.';
						}else{
							ans[h][i*2]='.';
							ans[h][i*2+1]='#';
						}
					}else{
						if (f){
							ans[h][i*2]='#';
						}else{
							ans[h][i*2]='.';
						}
						FOR(j,i*2+1,100){
							if (f){
								ans[h][j]='#';
							}else{
								ans[h][j]='.';
							}
							f=!f;
						}
						break;
					}
				}
				A-=min(A,50);
				h++;
				f=!f;
			}
			show();
		}
	}							
	return 0;
}

