template < class Value >
auto rotate180(std::vector< std::vector< Value > > const& a) {
  std::size_t h = a.size(), w = a.front().size();
  std::vector< std::vector< Value > > b(h, std::vector< Value >(w));
  for (std::size_t i = 0; i < h; i++) {
    for (std::size_t j = 0; j < w; j++) {
      b.at(h-1-i).at(w-1-j) = a.at(i).at(j);
    }
  }
  return b;
}

/*
上半分が白、下半分が黒なものを作って、穴を開ければよいです。
*/

int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int A, B; std::cin >> A >> B;
  A--,B--;
  int n = 100;
  int l = n / 2;
  auto grid = make_vector<2,int>(n,n);
  rep(i,l,n) rep(j,0,n) {
    at(grid,i,j) = 1;
  }

  loop(2) {
    for (int i = 1; i < n; i += 2) {
      if (A==0) break;
      for (int j = 1; j < n; j += 2) {
        if (A==0) break;
        at(grid,i,j) = 1;
        A--;
      }
    }

    assert(A==0);
    std::swap(A,B);
    grid = rotate180(grid);
    for (auto&& v : grid) {
      for (int & x : v)  {
        x ^= 1;
      }
    }
  }

  std::cout << n << " " << n << std::endl;
  for (auto&& v : grid) {
    rep(i,0,n) {
      std::cout << (v.at(i) ? '#' : '.');
    }
    std::cout << std::endl;
  }
  return 0;
}

