	int pos = -1;
	for (int i = 0; i < N; i++) {
		bool ok = true;
		for (int j = 0; j  < N; j++) {
			if(i == 0 && j == 0) {
				A[i][j] = 0;
				cnt[A[i][j]]--;
				continue;
			}
			if(j == 0) {
				A[i][j] = 1 - A[i - 1][j];
			}
			else {
				A[i][j] = 1 - A[i][j - 1];
			}
			if(cnt[A[i][j]] == 0) {
				for (int k = j; k < N; k++) {
					A[i][k] = A[i][k - 1];
				}
				ok = false;
				break;
			}
			cnt[A[i][j]]--;
		}
		if(!ok) {
			pos = i + 1;
			break;
		}
	}
	auto fill_all = [&](int def) {
		string s = ".#";
		cout << N << " " << N << "\n";
		for (int i = 0; i < N; i++) {
