		fill_all(0);
	}
	for (int j = 0; j < N; j++) {
		if(j == 0)
			A[pos][j] = 1 - A[pos - 1][j];
		else
			A[pos][j] = 1 - A[pos][j - 1];
		if(A[pos][j] != A[pos - 1][j] && cnt[A[pos][j]] == 1) {
			fill_all(1 - A[pos][j]);
			break;
		}
		if(A[pos][j] != A[pos - 1][j])
			cnt[A[pos][j]]--;
	}
	for (int j = 0; j < N; j++) {
		if(cnt[0] <= 0)
			A[pos + 1][j] = 0;
		else if(cnt[1] <= 0)
			A[pos + 1][j] = 1;
	}
	for (int i = pos + 2; i < N; i += 2) {
		for (int j = 0; j < N; j++) {
			A[i][j] = A[i - 2][j];
