const int N = 100;

int main() {
  int a, b;
  cin >> a >> b;
  --a, --b;
  vector<string> ans(N);
  ans[0] = ans[N - 1] = string(N / 2, '#') + string(N / 2, '.');
  for (int i = 1; i < N - 1; ++i)
    ans[i] = "#" + string(N / 2 - 2, '.') + "#" + "." + string(N / 2 - 2, '#') + ".";

  int c = 0, d = 0;
  for (int i = 1; i < N - 1; ++i) {
    for (int j = 1 + (i % 2); j < N / 2 - 1; j += 2) {
      if (a > 0) {
        --a;
        ++c;
        ans[i][j] = '#';
      }
    }
  }
  for (int i = 1; i < N - 1; ++i) {
    for (int j = 1; j < N / 2 - 1; ++j) {
      c -= (ans[i][j] == '#');
      if (c == 0)
        ans[i][j] = '#';
    }
  }
  for (int i = 1; i < N - 1; ++i) {
    for (int j = 1 + N / 2 + (i % 2); j < N - 1; j += 2) {
      if (b > 0) {
        --b;
        ++d;
        ans[i][j] = '.';
      }
    }
  }
  for (int i = 1; i < N - 1; ++i) {
    for (int j = N / 2 + 1; j < N - 1; ++j) {
      d -= (ans[i][j] == '.');
      if (d == 0)
        ans[i][j] = '.';
