const int max_size = 109;
int main(){
    int A,B;
    std::cin >> A >> B;
    std::vector<std::string>grid;
    --A;
    --B;
    int amod = A % (max_size / 2);
    std::string as,base,bs;
    for(int i = 0; i < amod; ++i)
        as.push_back('.'),as.push_back('#');
    while(as.size() < max_size) as.push_back('#');
    for(int i = 0; i < max_size /2; ++i)
        base.push_back('.'),base.push_back('#');
    for(int i = 0; i < A/(max_size / 2); ++i){
        grid.push_back(base);
        grid.push_back(std::string(max_size,'#'));
    }
    grid.push_back(as);
    grid.push_back(std::string(max_size,'#'));
    grid.push_back(std::string(max_size,'.'));
    int bmod = B % (max_size / 2);
    for(int i = 0; i < bmod; ++i)
        bs.push_back('.'),bs.push_back('#');
    while(bs.size() < max_size) bs.push_back('.');
    for(int i = 0; i < B / (max_size / 2); ++i){
        grid.push_back(base);
        grid.push_back(std::string(max_size,'.'));
    }
    grid.push_back(bs);
    std::cout << grid.size() << " " << max_size << std::endl;
    for(auto s : grid)
        std::cout << s << std::endl;

}

