    b += "#";
    w += ".";
  }
  rep(i, 0, k) {
    v[i] = b;
    v[i + k] = w;
  }
  auto inrange = [&](int x, int y) {
    return 0 <= x and x < 2*k and 0 <= y and y < 2 * k;
  };

