      continue;

    bool f = true;
    rep(k, 0, 4) {
      int X = x + dx[k], Y = y + dy[k];
      if (inrange(X, Y)) {
        f &= (v[X][Y] == v[x][y]);
      }
    }

    if (f)
      v[x][y] = '.', cnt++;
  }

  cnt = 0;
