const ll mod = 1000 * 1000 * 1000 + 7;

ll pw(ll a, ll n) {
    ll ret = 1;
    while (n) {
        if (n & 1) ret = ret * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return ret;
}

ll gcd(ll a, ll b) {
    a = std::abs(a);
    b = std::abs(b);
    while (b > 0) {
        a %= b;
        swap(a, b);
    }
    return a;
}

struct Q {
    ll n, d;
    Q(): n(0), d(1) {}
    Q(ll nn, ll dd) {
        n = nn;
        d = dd;
        ll g = gcd(n, d);
        n /= g;
        d /= g;
        if (d < 0) {
            n *= -1;
            d *= -1;
        }
    }

    bool operator < (const Q &r) const {
        return n * r.d < r.n * d;
    }
    bool operator <= (const Q &r) const {
        return n * r.d <= r.n * d;
    }
    bool operator == (const Q &r) const {
        return n * r.d == r.n * d;
    }
};


void solve() {
    int a, b;
    a = nxt();
    b = nxt();

    int n = 100, m = 100;
    vector<string> ans(n, string(m, '.'));
    for (int i = n / 2; i < n; ++i) {
        forn(j, m) {
            ans[i][j] = '#';
        }
    }
    --a, --b;
    for (int i = 1; i < n && b > 0; i += 2) {
        for (int j = 1; j < m && b > 0; j += 2) {
            ans[i][j] = '#';
            --b;
        }
    }
    for (int i = n / 2 + 1; i < n && a > 0; i += 2) {
        for (int j = 1; j < m && a > 0; j += 2) {
            ans[i][j] = '.';
            --a;
        }
    }
    cout << n << " " << m << "\n";
    forn(i, n) {
        cout << ans[i] << "\n";
    }
}



