void solve(long long A, long long B) {
  int MAXN = 100;
  vector<vector<int>> field(MAXN, vector<int>(MAXN, 0));

  for (int i = 0; i < MAXN / 2; i++) {
    for (int j = 0; j < MAXN; j++) {
      field[i][j] = 1;
    }
  }

  for (int i = 0; i < MAXN / 2; i += 2) {
    for (int j = 0; j < MAXN; j += 2) {
      if (A > 1) {
        A--;
        field[i][j] = 0;
      }
    }
  }

  for (int i = MAXN / 2 + 1; i < MAXN; i += 2) {
    for (int j = 0; j < MAXN; j += 2) {
      if (B > 1) {
        B--;
        field[i][j] = 1;
      }
    }
  }
  for (int i = 0; i < MAXN; i++) {
    for (int j = 0; j < MAXN; j++) {
      cout << (field[i][j] ? "#" : ".");
    }
    cout << endl;
  }
}

