    if(a>b)
        flag=1;
    else
        flag=0;
    if(a<b)
        swap(a,b);
    if(a>b){
        b--;
        for(int i=1;a>b;i+=2){
            for(int j=1;j<=100;j++){
                if(j%2==1&&a>b){
                    m[i][j]=1-flag;
                    a--;
                }
                else
                    m[i][j]=flag;
            }
            for(int j=1;j<=100;j++)
                m[i+1][j]=flag;
            cnt=i+1;
        }
    }
    for(int i=cnt+1;a;i+=4){
        a--;
        b--;
        if(a==0&&b==0){
            for(int j=1;j<=100;j++){
                m[i][j]=1-flag;
                m[i+1][j]=flag;
            }
            sum=i+1;
            break;
        }
        for(int j=1;j<=100;j++)
            m[i][j]=1-flag;
        for(int j=1;j<=100;j++)
            m[i+3][j]=flag;
        for(int j=1;j<=100;j++){
            if(a){
                if(j%2){
                    m[i+1][j]=1-m[i][j];
                    a--;
                }
                else
                    m[i+1][j]=m[i][j];
            }
            else
                m[i+1][j]=m[i+1][j-1];
        }
        for(int j=1;j<=100;j++)
            m[i+2][j]=1-m[i+1][j];
        sum=i+3;
    }
    print();
}

