	for (int i = 0; i < 100; i++)
	{
		if (A == 0 || B == 0)
		{
			if (grid[i - 1][0] == '.')
			{
				grid[i] = w;
			}
			else
			{
				grid[i] = b;
			}
			continue;
		}
		if (B == 1 && A == 1)
		{
			if (i == 0)
			{
				grid[i] = b;
				i++;
				grid[i] = w;
			}
			else
			{
				if (grid[i - 1][0] == '.')
				{
					grid[i] = b;
					i++;
					grid[i] = w;

				}
				else
				{
					grid[i] = w;
					i++;
					grid[i] = b;
				}
			}
			B--;
			A--;
			continue;
		}

		if (A >= B)
		{
			grid[i] = b;
			i++;
			string g = w;
			for (int j = 0; j < 100; ++j)
			{
				if (j % 2 == 1 || A == 1)
				{
					g[j] = '#';
				}
				else
				{
					g[j] = '.';
					A--;
				}
			}
			grid[i] = g;
			i++;
			grid[i] = b;
			if (A <= B) {
				B--;
			}
			continue;
		}
		if (B > A)
		{
			grid[i] = w;
			i++;
			string g = b;
			for (int j = 0; j < 100; ++j)
			{
				if (j % 2 == 1 || B == 1)
				{
					g[j] = '.';
				}
				else
				{
					g[j] = '#';
					B--;
				}
			}
			grid[i] = g;
			i++;
			grid[i] = w;
			if (A >= B) {
				A--;
			}
			continue;
		}
	}

	cout << 100 << " " << 100 << endl;

	for (int i = 0; i < 100; ++i) {
		cout << grid[i] << endl;
	}
	return 0;
}

