const int maxn = 98;
char num[maxn + 5][maxn + 5];
int A, B;
bool flag;
int main() {
	scanf("%d%d", &A, &B);
	if(A > B) {
		flag = true;
		swap(A, B);
	}
	int cnt_A = 0, cnt_B = 0;
	for(int i = 1; i <= maxn; i++)
		for(int j = 1; j <= maxn; j++)
			num[i][j] = '.';
	if(cnt_A < A - 1) {
		for(int i = 2; i <= maxn; i += 2) {
			num[1][i] = num[2][i - 1] = '#';
			cnt_A++;
			cnt_B++;
			if(cnt_A == A - 1) {
				for(int j = 2; j <= i; j += 2)num[2][j] = '#';
				cnt_B -= (i / 2);
				cnt_B++;
				break;
			}
		}
	}
	if(cnt_A < A - 1) {
		int l;
		for(int i = 3; i <= maxn; i++) {
			if(cnt_A == A - 1) break;
			if(i & 1)l = 2;
			else l = 1;
			for(int j = l; j <= maxn; j += 2) {
				num[i][j] = '#';
				cnt_A++;
				cnt_B++;
				if(cnt_A == A - 1) {
					for(int k = 1; k <= j; k++)num[i][k] = '#';
					for(int k = j + 1; k <= maxn; k++)num[i - 1][k] = '#';
					cnt_B -= maxn / 2 - 2;
					break;
				}
			}
		}
	}
	for(int i = maxn; i >= 1; i -= 2) {
		if(cnt_B == B)break;
		for(int j = 1; j <= maxn; j += 2) {
			if(cnt_B == B)break;
			num[i][j] = '#';
			cnt_B++;
		}
	}
	printf("100 100\n");
	for(int i = 1; i <= maxn; i++) {
		for(int j = 1; j <= maxn; j++)
			if(flag == true) {
				if(num[i][j] == '.')printf("#");
				else printf(".");
			}
			else printf("%c", num[i][j]);
		printf("\n");
	}
	return 0;
}

