					for(int j = 2; j <= i; j += 2)num[2][j] = '.';
					cnt_A -= (i / 2);
					cnt_A++;
					break;
				}
			}
		}
		if(cnt_B < B - 1) {
			int l;
			for(int i = 3; i <= maxn; i++) {
				if(cnt_B == B - 1)break;
				if(i & 1)l = 2;
				else l = 1;
				for(int j = l; j <= maxn; j += 2) {
					num[i][j] = '.';
					cnt_B++;
					cnt_A++;
					if(cnt_B == B - 1) {
						if(l == 1)l = 2;
						else if(l == 2)l = 1;
						for(int k = l; k <= j; k += 2)num[i][k] = '.';
						cnt_A -= j / 2;
						cnt_A++;
