inline int get_side(int x,int y)
{
	return a[x-1][y]+a[x+1][y]+a[x][y-1]+a[x][y+1];
}

int main()
{
	scanf("%d%d",&w,&b);
	n=m=100,W=w,B=b;
	if(w>b) swap(w,b);
	int x,y;
	for(int i=1;i<=n && cw<w;i++)
	{
		for(int j=1+(!(i&1));j<=m && cw<w;j+=2)
		{
			a[i][j]=1,cb++,x=i,y=j+1;
			if(i>1) cw++;
		}
	}
	// print();
	if(cb>b)
	{
		// cout<<"cb > b"<<endl;
		for(int j=1+(x&1);j<=m && cb>b;j+=2)
		{
			a[x][j]=1,cb-=get_side(x,j)-1;
			if(j==y) x--,j--;
		}
	}
	// print();
	if(cb<b)
	{
		// cout<<"cb < b"<<endl;
		for(int i=n;i>=1 && cb<b;i-=2)
		{
			for(int j=1;j<=m && cb<b;j+=2)
			{
				a[i][j]=1,cb++;
			}
		}
	}
	print();
}

