                int to_row = min(row + 3, MAXN-1);
                for (int j = row; j <= to_row; ++j) {
                    f[j][col] = '#';
                }
                --a;
            }
        }
    }
    --b;

    for (int r = 1; b && r < MAXN-1; r += 4) {
        for (int c = 1; b && c < MAXN-1; c += 4, --b) {
            f[r][c] = '#';
        }
