using namespace std;

typedef long long ll;
typedef pair<int,int> P;

int main() {
    int A, B;
    cin >> A >> B;

    int n;          // size of grid
    n = (int)sqrt(2 * max(A, B) + abs(A - B)) + 1;

    bool grid[MAX_N][MAX_N];        // true: white, false: black
    int white = 0, black = 0;       // num of white, black grid
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if ((i + j) % 2 == 0) {
                grid[i][j] = true;
                white += 1;
            } else {
                grid[i][j] = false;
                black += 1;
            }
        }
    }


    if (A > B){
        for (int i = 0; i < n && black > B; ++i) {
            for (int j = 0; j < n && black > B; ++j) {
                if ((i + j) % 2 == 0) {
                    grid[i][j] = false;
                    black -= 1;
                    white -= 1;
                    if (i == 0 && j != n - 1) {
                        black -= 1;
                    }
                }
            }
        }
        for (int i = 0; i < n && white < A; i += 2) {
            for (int j = 0; j < n && white < A; j += 2) {
                grid[i][j] = true;
                white += 1;
            }
        }
    } else {
        for (int i = 0; i < n && white > A; ++i) {
            for (int j = 0; j < n && white > A; ++j) {
                if ((i + j) % 2 == 1) {
                    grid[i][j] = true;
                    white -= 1;
                    black -= 1;
                    if (i == 0 && j != n - 1) {
                        white -= 1;
                    }
                }
            }
        }
        for (int i = 0; i < n && black < B; i += 2) {
            for (int j = 0; j < n && black < B; j += 2) {
                grid[i][j] = false;
                black += 1;
            }
        }

    }

    cout << n << " " << n << endl;
    for (int i = 0; i < n; ++i) {
        string str;
        for (int j = 0; j < n; ++j) {
            if (grid[i][j])
                str += ".";
            else
                str += "#";
            str += " ";
        }
        cout << str << endl;
    }

    return 0;
}

