using namespace std;

int main(){
	ios_base::sync_with_stdio(false);
	const int n = 100, m = 25;
	int a, b;
	cin >> a >> b;
	bool swap_flag = (a < b);
	if(swap_flag){ swap(a, b); }
	vector<string> grid(n, string(n, '.'));
	for(int i = 0; i < n; i += 4){
		for(int j = 0; j < n; ++j){ grid[i][j] = '#'; }
		for(int j = 0; j < n; ++j){ grid[j][i] = '#'; }
	}
	--b;
	for(int i = a; i < m * m; ++i){
		const int r = (i / m) * 4, c = (i % m) * 4;
		for(int y = 1; y < 4; ++y){
			for(int x = 1; x < 4; ++x){ grid[r + y][c + x] = '#'; }
		}
	}
	for(int i = 0; i < b; ++i){
		const int r = (i / m) * 4, c = (i % m) * 4;
		grid[r + 2][c + 2] = '#';
	}
	if(swap_flag){
		for(auto& s : grid){
			for(auto& c : s){
				if(c == '.'){
					c = '#';
				}else{
					c = '.';
				}
			}
		}
	}
	cout << n << " " << n << endl;
	for(const auto& s : grid){
		cout << s << endl;
	}
	return 0;
}

