using namespace std;

char f(int a, int b)
{
    if (a < b)
        return '.';
    return '#';
}

int main()
{
    ios_base::sync_with_stdio(false);
    int a, b;
    cin >> a >> b;
    int h = 100, w = 100;
    int c = min(a, b) - 1;
    c += c;

    vector < vector <char> > ans(h, vector <char> (w, f(a, b)));
    char r = (f(a, b) == '.' ? '#' : '.');
    int i = 0, j = 0;
    int cc = 0;

    for (i = 0; c && (i < h); i++)
    {
        for (j = 0; c && (j < w); j++)
        {
            if ((i + j) % 2 == 0) {
                ans[i][j] = r;
                cc++;
            }
            c--;
            if (c == 0) break;
        }
        if (c == 0) break;
    }
    if (j & 1) j++;

    for (int k = j; k < w; k++)
        ans[i][k] = r;
    for (int k = 0; k < w; k++)
        ans[i + 1][k] = r;

    if (i - 1 >= 0)
    {
        for (int k = j; k < w; k++)
        {
            if (ans[i - 1][k] == r)
                cc--;
        }
    }
    for (int k = 0; k < j; k++)
        if (ans[i][k] == r)
            cc--;
    cc++;
    int t = 0;
    while (cc < max(a, b))
    {
        i = (t / (h / 2)) * 2;
        j = (t % (w / 2)) * 2;
        ans[h - 1 - i][w - 1 - j] = r;
        t++, cc++;
    }
    cout << h << ' ' << w << '\n';
    for (int i = 0; i < h; i++)
    {
        for (int j = 0; j < w; j++)
        {
            cout << ans[i][j];
        }
        cout << '\n';
    }
    return 0;
}

