const int N = 100;
int T[N][N], A, B;

void solve() {
	A = fetch<int>() - 1;
	B = fetch<int>() - 1;

	for(int i = 0; i < N; ++i) {
		for(int j = 0; j < N; ++j) {
			T[i][j] = (j < N / 2);
		}
	}

	for(int i = 0; i < N; ++i) {
		for(int j = 0; j < N / 2 - 1; ++j) {
			int t = (i & 1) ^ (j & 1);

			if(t && A > 0) {
				T[i][j] = 0;
				--A;
			}
		}

		for(int j = N / 2 + 1; j < N; ++j) {
			int t = (i & 1) ^ (j & 1);

			if(t && B > 0) {
				T[i][j] = 1;
				--B;
			}
		}
	}

	cout << N << ' ' << N << '\n';

	for(int i = 0; i < N; ++i) {
		string line(N, '$');

		for(int j = 0; j < N; ++j) {
			line[j] = (T[i][j] ? '#' : '.');
		}

		cout << line << '\n';
	}
}

