  rep( i, 2*K ) rep( j, 2*K )
    fld[i][j] = i<K ? 0 : 1;

  int cnt = 0;

  rep( i, K ) rep( j, 2*K ) if( !(i&1) )
  {
    bool fl = !fld[i][j];

    rep( d, 4 )
