void solve(ll A, ll B) {
  int H = 100, W = 100;
  vector<string> res(H, string(W, '.'));
  REP(i,H/2) REP(j,W) res[i][j] = '#';
  REP(i,H/4) REP(j,W/2) {
    if (A > 1) { res[i * 2][j * 2] = '.'; --A; }
    if (B > 1) { res[H - 1 - i * 2][j * 2] = '#'; --B; }
  }
  cout << H << " " << W << endl;
  REP(i,H) cout << res[i] << endl;
}

