  int len = base + 2 * abs(A - B);
  vector<string> ans(2, string(len, '.'));
  char fill = (A > B ? '#' : '.');
  char other = (A > B ? '.' : '#');
  FOR(i, len) {
    if (i < base) {
      ans[i % 2][i] = '#';
      ans[(i + 1) % 2][i] = '.';
    } else {
      if ((i - base) % 2 == 0) {
        ans[0][i] = fill;
        ans[1][i] = fill;
      } else {
        ans[0][i] = fill;
        ans[0][i] = other;
      }
    }
  }
  cout << 2 << " " << len << endl;
  cout << ans[0] << endl;
  cout << ans[1] << endl;
  return 0;
}

