const int N=1e5+10;

string ch=".#";
int n,m;

int ans[100][100];
void solve(){
        if (n==1){
                cout<<"100 100\n";
                for(int i=0;i<100;i++){
                        for(int j=0;j<100;j++){
                                if (i%2&&j%2&&m) {
                                        cout<<ch[1];
                                        m--;
                                }else cout<<ch[0];
                        }
                        cout<<'\n';
                }
                return;
        }
        ///split 50-50
        for(int i=0;i<100;i++)
                ans[50][i]=1;
        n--,m--;
        for(int type=0;type<=1;type++){
                int st=type*50;
                for(int i=0;i<49;i++)
                        for(int j=0;j<100;j++) {
                                if (i%2&&j%2&&m) {
                                        ans[st+i][j]=type^1;
                                        m--;
                                }else ans[st+i][j]=type;

                        }
                swap(n,m);
        }
        for(int i=0;i<100;i++){
                for(int j=0;j<100;j++) cout<<ch[ans[i][j]];
                cout<<'\n';
        }
}
int main(){
        cin>>n>>m;
        if (n>m){
                swap(n,m);
                swap(ch[0],ch[1]);
        }
        solve();
}

