#include <bits/stdc++.h>

using namespace std;

const int n = 100, N = 101;
int ans[N][N];

int main() {
    //freopen("input.txt", "r", stdin);
    int a, b;
    cin >> a >> b;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (j <= n / 2) {
                ans[i][j] = 0;
            } else {
                ans[i][j] = 1;
            }
        }
    }
    a -= 1;
    b -= 1;
    int curRow = 1;
    while (b >= 1) {
        for (int j = 1; j <= n / 2 - 1; ++j) {
            if (0 == b) {
                break;
            }
            if (j % 2 == 1) {
                ans[curRow][j] = 1;
                --b;
            }
        }
        curRow += 2;
    }
    curRow = 1;
    while (a >= 1) {
        for (int j = n / 2 + 1; j <= n; ++j) {
            if (0 == a) {
                break;
            }
            if (j % 2 == 1) {
                ans[curRow][j] = 0;
                --a;
            }
        }
        curRow += 2;
    }
    printf("%d %d\n", n, n);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (ans[i][j] == 1) {
                printf("#");
            } else {
                printf(".");
            }
        }
        printf("\n");
    }
    return 0;
}

