    for(int i = 3; i < 100 && A > 0; i += 4){
        for(int j = 0; j < 100; j++){
            field[i][j] = '#';
        }
        A-=25;
    }

    // 幅優先探索で塗って帳尻合わせ
    for(int i = 0; i < 100 && A < 0; i++){
        for(int j = 0; j < 100 && A < 0; j++){
