                        if(ny >= 0 && nx >= 0 && ny < 100 && nx < 100 && field[ny][nx] == '.'){
                            field[ny][nx] = '#';
                            q.push(pii(ny, nx));
                        }
                    }
                }
                A++;
            }
        }
    }

    for(int i = 0; i < 100; i++){
        for(int j = 0; j < 100; j++){
            if(B == 0)continue;
