                    int ni = i + dy;
                    int nj = j + dx;
                    if(ni >= 0 && nj >= 0 && ni < 100 && nj < 100 && field[ni][nj] == '#'){
                        ok = false;
                    }
                }
            }

            if(ok){
                field[i][j] = '#';
                B--;
            }
        }
    }



    cout << 100 << " " << 100 << endl;
    for(int i = 0; i < 100; i++){
        for(int j = 0; j < 100; j++){
