    for (int j = 0; j < 2*K; j++)
    {
      vv[i][j] = 1;
    }
  }
  int cntA = 0, cntB = 0;
  for (int i = 0; i < K; i++)
  {
    for (int j = 0; j < 2*K; j++)
    {
      if(i%2 == 0 && j%2 == 0 && cntA < A)
      {
        vv[i][j] ^=1;
        cntA++;
      } 
    }
  }

  for (int i = K; i < 2*K; i++)
  {
    for (int j = 0; j < 2*K; j++)
    {
      if(i%2 == 1 && j%2 == 0 && cntB < B)
      {
        vv[i][j] ^=1;
        cntB++;
      } 
    }
  }
  cout<<2*K <<" "<<2*K<<endl;
  for (int i = 0; i < 2*K; i++)
