  bool lessWhite;
  int dif;
  int equal;
  if(A<=B){
	lessWhite = true;
	dif = B-A;
	equal = A;
  }else{
	lessWhite = false;
	dif = A-B;
	equal = B;
  }
  for(int i = 0; i < 100; i++)
	for(int j = 0; j < 100; j++)
	  check_field[i][j] = false;
  int rowCount = 0;
  int setCount = 0;
