void dfs (int i, int j) {
	u[i][j] = 1;
	for (int l = 0; l < 4; l ++) {
		static int ni, nj;
		ni = dx[l] + i, nj = dy[l] + j;

		if (ni < 1 || nj < 1 || ni > n || nj > n) {
			continue;
		}
		if (arr[ni][nj] != arr[i][j] || u[ni][nj]) continue;
		dfs(ni, nj);
	}	
}

pair < int, int > cnt_numb () {
	pair < int, int > res = mp(0, 0);

	memset(u, 0, sizeof u);

	for (int i = 1; i <= n; i ++) {
		for (int j = 1; j <= n; j ++) {
			if (u[i][j]) continue;
			if (arr[i][j] == '#') {
				dfs(i, j);
				++ res.F;
			} else {
				dfs(i, j);
				++ res.S;
			}
		}
	}

	return res;
}

