				arr[i][j] = '.';
			} else {
				arr[i][j] = '#';
			}
		}
	}

	arr[2][1] = '#';
	arr[n][n] = '.';


	pair < int, int > cur = cnt_numb ();


	while (a < cur.F || cur.S > b) {
		pair < int, int > now;
		if(a < cur.F) {
			for (int i = 1; i <= n; i ++) {
				for (int j = 1; j <= n; j ++) {
					if(change[i][j]) continue;
					if (arr[i][j] == '#') {
						arr[i][j] = '.';
						now = cnt_numb();

						if (now.F < cur.F && now.F >= a) {
							break;
						}
						arr[i][j] = '#';
					}
				}
				if(now.F < cur.F) break;
			}
