int A, B;
int Min, Max;
char s[120][120], ans[120][120];

void Init() {
	for(int i = 1; i <= 100; i++)
		for(int j = 1; j <= 100; j++)
			s[i][j] = '@';
	Min = inf; Max = 0;
	Min = min(A, B);
	Max = max(A, B);
}

void enlarge(int x, int y) {
	for(int i = 0; i < 4; i++)
		s[4 * x][4 * y - i] = 'a';
	for(int i = 0; i < 4; i++)
		s[4 * x - i][4 * y] = 'a';
	s[4 * x - 2][4 * y - 2] = 'a';
}

void get() {
	int num = 0;
	bool f = 1;
	if(Min > 1) {
		for(int R = 1; R <= 20; R++) {
			f = 1;
			for(int C = 1; C <= 25; C++) {
				num++;
				if(num > (Min - 1)) {
					f = 0;
					break;
				}
				enlarge(R, C);
			}
			if(f == 0) break;
		}
	}
	int all = Max - Min;
	if(Min == 1) all++;
	int cnt = 0;
	for(int R = 100; R >= 79; R--) {
		f = 1;
		for(int C = 1; C <= 49; C++) {
			cnt++;
			if(cnt > all) {
				f = 0;
				break;
			}
			if(R & 1) s[R][2 * C] = 'a';
			else s[R][2 * C - 1] = 'a';
		}
		if(f == 0) break;
	}
}

void solve() {
	get();
	if(A <= B) {
		for(int i = 1; i <= 100; i++) {
			for(int j = 1; j <= 100; j++) {
				if(s[i][j] == 'a') ans[i][j] = '#';
				else ans[i][j] = '.';
			}
		}
	}
	else {
		for(int i = 1; i <= 100; i++) {
			for(int j = 1; j <= 100; j++) {
				if(s[i][j] == 'a') ans[i][j] = '.';
				else ans[i][j] = '#';
			}
		}
	}
}

int main()
{
	while(scanf("%d %d", &A, &B) != EOF)
	{
		Init();
		solve();
		printf("100 100\n");
		for(int i = 1; i <= 100; i++) {
			for(int j = 1; j <= 100; j++)
				printf("%c", ans[i][j]);
			printf("\n");
		}
	}
	return 0;
}

