using namespace std;

ll power(ll a,ll b,ll m){
	ll x=1%m; a%=m;
	while(b){
		if((1&b)) x = x * a % m;
		a = a * a % m;
		b >>= 1;
	}
	return x;
}

char mat[105][105];

void build(int a,int b){
	for(int i=0;i<100;i++) mat[i][100]='\0';
	// by default paint entire with small one
	char small = (a<=b)?'.':'#';
	for(int i=0;i<100;i++){
		for(int j=0;j<100;j++) mat[i][j]=small;
	}
	char bada = (a>b)?'.':'#';
	int mx = max(a,b);
	int mn = min(a,b) - 1;
	for(int i=0;i+2<100;i+=4){
		for(int j=0;j+2<100;j+=4){
			if(!mx) break;
			mx--;
			for(int ii=i;ii<i+3;ii++){
				for(int jj=j;jj<j+3;jj++) mat[ii][jj]=bada;
			}
			if(mn){
				mn--;
				mat[i+1][j+1]=small;
			}
		}
	}
}

