using namespace std;

int main() {
    int A, B;
    cin >> A >> B;

    if (A == 1 && B == 1) {
        cout << "1 2" << endl;
        cout << "#." << endl;
        return 0;
    }

    bool rev = A < B;
    if (rev) {
        swap(A, B);
    }

    for (int i = 1; i <= 500; i++) {
        for (int j = 1; j <= 500; j++) {
            int b;
            if (i % 2 == 0 && j % 2 == 0) {
                b = i / 2 * j;
            } else if (i % 2 == 1 && j % 2 == 1) {
                b = (i * j + 1) / 2;
            } else {
                b = (i + 1) / 2 * (j + 1) / 2;
            }

            //外周にあるWの数
            int outer_w;
            if (i % 2 == 0 && j % 2 == 0
                || i % 2 == 1 && j % 2 == 1) {
                outer_w = i / 2 + j / 2;
            } else {
                outer_w = i / 2 + j / 2 - 1;
            }

            int inner_w = i * j - b - outer_w;

            if (b != A || inner_w >= B || (inner_w + outer_w) < B) {
                //無理なので次へ行く
                continue;
            }

            //OKだということ
            cout << i + 1 << " " << j + 1 << endl;
            vector<string> ans(i + 1, "");
            for (int k = 0; k <= i; k++) {
                for (int l = 0; l <= j; l++) {
                    ans[k] += "*";
                }
            }
            for (int k = 0; k < i; k++) {
                //市松模様
                for (int l = 0; l < j; l++) {
                    ans[k][l] = (k + l) % 2 == 0 ? '#' : '.';
                }
            }

            //外周を上手く埋めてouter_wをrest個にする
            int rest = B - inner_w;

            for (int k = 0; k < i; k++) {
                if (rest == 0) {
                    ans[k][j] = '.';
                } else {
                    ans[k][j] = ans[k][j - 1];
                    if ((k + j) % 2 == 0) {
                        rest--;
                    }
                }
            }
            for (int l = 0; l < j; l++) {
                if (rest == 0) {
                    ans[i][l] = '.';
                } else {
                    ans[i][l] = ans[i - 1][l];
                    if ((i + l) % 2 == 0) {
                        rest--;
                    }
                }
            }

            ans[i][j] = ans[i][j - 1];

            for (int k = 0; k <= i; k++) {
                for (int l = 0; l <= j; l++) {
                    //cout << ans[k][l];
                    if (!rev) {
                        cout << ans[k][l];
                    } else {
                        cout << (ans[k][l] == '#' ? '.' : '#');
                    }
                }
                cout << endl;
            }
            return 0;

        }
    }
}

