int main() {
	vector <int> cnt(2);
	cin >> cnt[0] >> cnt[1];
	const int N = 99;
	vector <vector<int>> A(N, vector<int>(N, -1));
	int pos = -1;
	for (int i = 0; i < N; i++) {
		bool ok = true;
		for (int j = 0; j  < N; j++) {
			if(i == 0 && j == 0) {
				A[i][j] = 0;
				cnt[A[i][j]]--;
				continue;
			}
			if(j == 0) {
				A[i][j] = 1 - A[i - 1][j];
			}
			else {
				A[i][j] = 1 - A[i][j - 1];
			}
			if(cnt[A[i][j]] == 0) {
				for (int k = j; k < N; k++) {
					A[i][k] = A[i][k - 1];
				}
				ok = false;
				break;
			}
			cnt[A[i][j]]--;
		}
		if(!ok) {
			pos = i + 1;
			break;
		}
	}
	auto fill_all = [&](int def) {
		string s = ".#";
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < N; j++) {
				if(A[i][j] == -1)
					A[i][j] = def;
				cout << s[A[i][j]];
			}
			cout << "\n";
		}
		exit(0);
	};
	if(cnt[0] == 0 && cnt[1] == 0) {
		fill_all(0);
	}
	for (int j = 0; j < N; j++) {
		if(j == 0)
			A[pos][j] = 1 - A[pos - 1][j];
		else
			A[pos][j] = 1 - A[pos][j - 1];
		if(A[pos][j] != A[pos - 1][j] && cnt[A[pos][j]] == 1) {
			fill_all(1 - A[pos][j]);
			break;
		}
		if(A[pos][j] != A[pos - 1][j])
			cnt[A[pos][j]]--;
	}
	for (int j = 0; j < N; j++) {
		if(cnt[0] <= 0)
			A[pos + 1][j] = 0;
		else if(cnt[1] <= 0)
			A[pos + 1][j] = 1;
	}
	for (int i = pos + 2; i < N; i += 2) {
		for (int j = 0; j < N; j++) {
			A[i][j] = A[i - 2][j];
			if(cnt[A[i][j]] == 1) {
				fill_all(1 - A[i][j]);
				break;
			}
			cnt[A[i][j]]--;
			if(cnt[0] <= 0)
				A[i + 1][j] = 0;
			else if(cnt[1] <= 0)
				A[i + 1][j] = 1;
		}
	}
}

