	void init(int n) { data.assign(n, -1); }
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) { return root(x) == root(y); }
	int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
	int size(int x) { return -data[root(x)]; }
};

int main() {
	int A, B;
	while (~scanf("%d%d", &A, &B)) {
		const int X = 40, Y = 20;
		int H = (Y + 1) * 4, W = X * 2 + 1;
		vector<string> ans(H, string(W, '.'));
		rep(i, H / 2 - 1) rep(j, W)
			ans[i][j] = '#';
		rep(j, W - 1) ans[H / 2][j] = '#';
		ans[H / 2 - 1][0] = '#';
		ans[H / 2 + 1][0] = '#';
		int k = Y * X;
		rep(j, X) rep(i, Y) {
			int y = i * 2 + 1, x = j * 2 + 1;
			ans[y][x] = '.';
			if (k >= A) ans[y + 1][x] = '.';
			ans[H - 1 - y][x] = '#';
			if (k >= B)ans[H - 1 - (y + 1)][x] = '#';
			-- k;
		}
		printf("%d %d\n", H, W);
		for (auto &&s : ans)
			puts(s.c_str());
	}
	return 0;
}

