#define N 100

char mp[N][N+1];

void calc(int a, int b){
  bool swapped = a<b;
  if(swapped)swap(a,b);
  // white is greater than black
  REP(i,N)REP(j,N)mp[i][j] = '.';
  REP(i,N)mp[i][0] = '#';
  int cnt = 1;
  REP(i,N)FOR(j,2,N)if(i%2==1 && j%2==0)mp[i][j] = '#', cnt++;
  REP(i,N)FOR(j,1,N-1)if(i%2==1 && j%2==1 && cnt>b)mp[i][j] = '#', cnt--;
  cnt = 1;
  REP(i,N)FOR(j,2,N)if(i%2==0 && j%2==0 && cnt<a)mp[i][j]='#', cnt++;

  if(swapped)REP(i,N)REP(j,N)mp[i][j] = mp[i][j]=='.' ? '#' : '.';
}

bool used[N][N];
int ddd[] = {1,0,-1,0,1};
void dfs(int i,int j){
  used[i][j] = true;
  REP(d,4){
    int ni = i + ddd[d];
    int nj = j + ddd[d+1];
    if(ni<0 || nj<0 || ni>=N || nj>=N)continue;
    if(used[ni][nj])continue;
    if(mp[ni][nj] != mp[i][j])continue;
    dfs(ni,nj);
  }
}

