    int n = 99;
///    int n = 29;
    vector<vector<bool>> ans(n, vector<bool>(n, bs));
    REP (i, 0, n) ans[0][i] = ans[n - 1][i] = ans[i][0] = ans[i][n - 1] = !bs;
    int interval = 4;
    int cnt = 1;

    // yoko
    for (int i = interval; i < n - 1 && cnt < B; i += interval, cnt++) {
        REP (j, 0, n) ans[i][j] = !bs;
    }

    // tate
    for (int i = interval; i < n - 1 && cnt < B; i += interval) {
        int idx = 0;
        while (idx < n - 1 && cnt < B) {
            while (idx < n - 1 && ans[idx][i] == !bs) idx++;
            for (; idx < n - 1 && cnt < B && ans[idx][i] == bs; idx++) ans[idx][i] = !bs;
            cnt++;
        }
    }

    A--;
//    if (A == B) A--;
    for (int i = 2; i < n - 1 && A > 0; i += interval) {
        for (int j = 2; j < n - 1 && A > 0; j += interval, A--) {
            ans[i][j] = !bs;
        }
    }

    REP (i, 0, n) {
        REP (j, 0, n) {
            cout << (ans[i][j] ? '.' : '#');
        }
        cout << endl;
    }
    return 0;
}

