    bool flag=true;
    if(a<b) swap(a,b),flag=false;
    int m=a-b;
    int cnt=0,cx=0,cy=0;
    while(cnt!=m){
            g[cy][cx]=true;
            g[cy][cx+1]=g[cy+1][cx]=g[cy+1][cx+1]=false;
            cx+=2;
            ++cnt;
            if(cx==100){
                cy+=2;cx=0;
            }
    }
    FOR(i,cx,100) g[cy][i]=g[cy+1][i]=false;
    bool f=false;
