    int sub=b-1;
    cnt=0;
    while(cnt!=sub){
        g[cy][cx]=g[cy+1][cx+1]=true;
        g[cy][cx+1]=g[cy+1][cx]=false;
        cx+=2;++cnt;
        if(cx==100) cy+=2,cx=0;
    }
    if(cx!=0) cy+=2;
    FOR(i,cx,100) g[cy-1][i]=true;
    if(!f)rep(i,100) g[cy][i]=true;
    if(!f)++cy;
