const int N = 100;

char res[N + 10][N + 10];

void work(int i, char x, int cc) {
   int j = 0;
   while(cc > 0) {

      res[i][j] = x;

      j += 2;

      if(j >= N) {
         i += 2;
         j = 0;
      }

      cc--;
   }

}

int main() {
   int a, b; scanf("%d%d", &a, &b);

   for(int i = 0; i < N/2; i++) {
      fill(res[i], res[i] + N, '#');
   }
   for(int i = N/2; i < N; i++) {
      fill(res[i], res[i] + N, '.');
   }

   work(0, '.', a-1);
   work(N/2+1, '#', b-1);

   printf("%d %d\n", N, N);
   for(int i = 0; i < N; i++) {
      printf("%s\n", res[i]);
   }
}

