#include <bits/stdc++.h>
using namespace std;

const int N = 100;
const int dx[] = {0, 1, 0, -1};
const int dy[] = {-1, 0, 1, 0};

bool vis[N][N];

bool valid(int y, int x) {
  return y >= 0 && x >= 0 && y < N && x < N;
}

void dfs(int y, int x, const vector<string> &ans) {
  vis[y][x] = true;
  for (int d = 0; d < 4; ++d) {
    int ny = y + dy[d];
    int nx = x + dx[d];
    if (valid(ny, nx) && ans[y][x] == ans[ny][nx] && !vis[ny][nx])
      dfs(ny, nx, ans);
  }
}

void solve(const vector<string> &ans) {
  memset(vis, false, sizeof vis);
  int b = 0, w = 0;
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < N; ++j) {
      if (!vis[i][j]) {
        if (ans[i][j] == '.') {
          dfs(i, j, ans);
          ++b;
        }
        if (ans[i][j] == '#') {
          dfs(i, j, ans);
          ++w;
        }
      }
    }
  }
  for (int i = 0; i < N; ++i)
    cout << ans[i] << '\n';
  cout << b << ' ' << w << '\n';
}

int main() {
  int a, b;
  cin >> a >> b;
  --a, --b;
  vector<string> ans(N);
  ans[0] = ans[N - 1] = string(N / 2, '#') + string(N / 2, '.');
  for (int i = 1; i < N - 1; ++i)
    ans[i] = "#" + string(N / 2 - 2, a ? '.' : '#') + "#" + "." + string(N / 2 - 2, b ? '#' : '.') + ".";
  int c = 0, d = 0;
  for (int i = 2; i < N - 1; i += 2) {
    if (a > 0) {
      --a;
      ++c;
      for (int j = 1; j < N / 2 - 1; ++j)
        ans[i][j] = '#';
    }
    if (b > 0) {
      --b;
      ++d;
      for (int j = N / 2 + 1; j < N - 1; ++j)
        ans[i][j] = '.';
    }
  }
  if (a == 0) {
    int start = 1 + 2 * c;
    for (int i = start; i < N - 1; ++i)
      for (int j = 1; j < N / 2 - 1; ++j)
        ans[i][j] = '#';
  }
  if (b == 0) {
    int start = 1 + 2 * d;
    for (int i = start; i < N - 1; ++i)
      for (int j = N / 2 + 1; j < N - 1; ++j)
        ans[i][j] = '.';
  }
  for (int i = 1; i < N - 1; i += 2) {
    for (int j = 2; j < N / 2 - 2; j += 2)
      if (a > 0)
        --a, ans[i][j] = '#';
    for (int j = N / 2 + 2; j < N - 2; j += 2)
      if (b > 0)
        --b, ans[i][j] = '.';
  }
  cout << "100 100" << '\n';
  for (int i = 0; i < N; ++i)
    cout << ans[i] << '\n';
  return 0;
}

