/*
Let k = 50 and prepare a grid of dimensions 2K * 2K
Paint all cells in the topmost K rows black. Paint the other cells White
From the topmost K rows, choose A - 1 cells such that no tow chosen cells are 4-adjacent and paint them white
From the bottommost K rows, choss B - 1 cells such that no tow chosen cells are 4-adjacent and paint them black.
*/ 
#include <bits/stdc++.h>

using namespace std;

const int MAXN = 105;

char board[MAXN][MAXN];

int A, B, K = 50;

int main()
{
    ios::sync_with_stdio(false); cin.tie(0);
    cin >> A >> B, --A, --B;
    for (int i = 0; i < (K << 1); i++)
    	for (int j = 0; j < (K << 1); j++)
    		board[i][j] = (i < K ? '#' : '.');
    for (int i = 0; i < K; i += 2)
    	for (int j = 0; j < (K << 1); j++)
    		if ((i + j) % 2 == 0 && A)
    			board[i][j] = '.', --A;
    for (int i = K + 1; i < (K << 1); i += 2)
    	for (int j = 0; j < (K << 1); j++)
    		if ((i + j) % 2 == 0 && B)
    			board[i][j] = '#', --B;
    cout << 100 << " " << 100 << endl;
    for (int i = 0; i < (K << 1); i++)
    {
    	for (int j = 0; j < (K << 1); j++)
    		cout << board[i][j];
    	cout << endl;
	}
	return 0;
}

