}

int c[N][N];

int dx[5]={0,1,0,-1};
int dy[5]={1,0,-1,0};

bool vis[N][N];

int main()
{

  int w = read(); int b=read(); int x=1; int y=0; int r=0;
  for(int i=1;i<=max(w,b);i++)
  {
    y++; if(y==98){x++; y=1;} c[x][y] = r; r^=1;

    y++; if(y==98){x++; y=1;} c[x][y] = r; r^=1;

  }

  if(y!=1)
  {
    if(x==1) for(int i=y+1;i<=97;i++) c[x][i] = c[x][i-1];
    else
    {
      if(y+1<=97) c[x][y+1] = c[x][y] ^ 1;
      else c[x][y+1] = c[x][y];
      for(int i=y+2;i<=97;i++) c[x][i] = c[x-1][i];
    }
  }

  for(int i=1;i<=97;i++)
  {
    c[0][i] = c[1][i];
    c[x+1][i] = c[x][i];
    c[i][0] = c[i][1];
    c[i][98] = c[i][97];
  }c[0][0] = c[1][1]; c[0][98] = c[1][97]; c[x+1][0] = c[x][1]; c[x+1][98] = c[x][97];

  int f=abs(w-b); int x1=0,y1=1; int col = 0;

  memset(vis,0,sizeof(vis));

  if(w<b) y1++,col=1; int dir=0; bool bk=0;
  while(f)
  {
