    for (int i = 0; i < h / 2; ++i) {
        for (int j = 0; j < w; ++j) {
            color[i][j] = 0;
        }
    }

    for (int i = h / 2; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            color[i][j] = 1;
        }
    }

    int per_row = 50;

    for (int i = 0; i < num_white_components - 1; ++i) {
        int row_idx = i / per_row;
        int col_idx = i % per_row;
        col_idx *= 2;
        row_idx *= 2;

        color[row_idx][col_idx] = 1;
    }

    for (int i = 0; i < num_black_components - 1; ++i) {
        int row_idx = i / per_row;
        int col_idx = i % per_row;
        col_idx *= 2;
        row_idx *= 2;

        color[h - row_idx - 1][col_idx] = 0;
    }

    printf("%d %d\n", h, w);
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            printf("%c", color[i][j] ? '.' : '#');
        }
        printf("\n");
    }

    return 0;
}

