	{
		for (int j = 0;j < 100;j++)
		{
			mp[i][j] = 1;
		}
	}

	int x = 0,y = 0;

	while (a)
	{
		mp[x][y] = 0;

		a--;

		y += 2;

		if (y >= 100)
		{
			x += 2;
			y = 0;
		}
	}

	x = 99,y = 0;

	while (b)
	{
		mp[x][y] = 1;

		y += 2;

		b--;

		if (y >= 100)
		{
			x -= 2;
			y = 0;
		}
	}

