int main()
{
  int A, B;
  cin >> A >> B;

  const int K = 50;
  int grid[2*K][2*K] ;

  for (int y = K; y<2*K; y++) {
    for (int x = 0; x < 2*K; x++) {
      grid[y][x] = 1; // 1 is for white, 0 is for black.
    }
  }

  // A is for white, .
  // B is for black, #

  int restA = A-1;
  for (int y = 0; y<K-1; y++) {
    for (int x = 0; x < 2*K; x++) {
      if ( (restA!=0) && (x%2==0)) {
        restA--;
        grid[y][x] = 1;
      }
    }
  }
  int restB = B-1;

  for (int y = K; y<2*K; y++) {
    for (int x = 0; x < 2*K; x++) {
      if ( (restB!=0) && (x%2==0)) {
        restB--;
        grid[y][x] = 0;
      }
    }
  }


  cout << "100 100" << endl;
  for (int y = 0; y < 2*K; y++) { 
    for (int x = 0; x < 2*K; x++){
      if (grid[y][x] == 0) {
        cout << ".";
      } else {
        cout << "#";
      }
    }
    cout << endl;
  }
}

