        for (int j = 0; j < 2*k; j++) {
            bool ok = true;
            for (int id = 0; id < idx; id++) {
                int di = i + dh[id], dj = j + dw[id];
                if (di < 0 || 2*k <= di) continue;
                if (dj < 0 || 2*k <= dj) continue;
                if (s[di][dj] == white) ok = false;
            }
            if (ok) { s[i][j] = white; pa++; }
            if (pa == a-1) break;
        }
        if (pa == a-1) break;
    }

    for (int i = 2*k-1; i > k; i--) {
        for (int j = 0; j < 2*k; j++) {
            bool ok = true;
            for (int id = 0; id < idx; id++) {
                int di = i + dh[id], dj = j + dw[id];
                if (di < 0 || 2*k <= di) continue;
                if (dj < 0 || 2*k <= dj) continue;
                if (s[di][dj] == black) ok = false;
            }
            if (ok) { s[i][j] = black; pb++; }
            if (pb == b-1) break;
        }
        if (pb == b-1) break;
    }
    return s;
}

