using vvvmll = std::vector<vvmll>;
using vvvvmll = std::vector<vvvmll>;


ll W = 100;
ll H = 100;

void solve()
{
  ll A,B; cin>>A>>B;
  bool isRev = false;
  if (A>B){
    isRev = true;
    swap(A,B);
  }

  vvll grid(H, vll(W));

  ll blackCount=0;
  REP(i, H/4){
    if (blackCount >= B) break;
    REP(j, W/4){
      if (blackCount >= B) break;
      ll ii = i*4, jj = j*4;
      REP(x, 3)REP(y, 3) grid[ii+x][jj+y] = 1;
      blackCount++;
    }
  }

  ll whiteCount=1;
  REP(i, H/4){
    if (whiteCount >= A) break;
    REP(j, W/4){
      if (whiteCount >= A) break;
      ll ii = i*4, jj = j*4;
      grid[ii+1][jj+1] = 0;
      whiteCount++;
    }
  }

  if (isRev){
    REP(i, H)REP(j, W) grid[i][j] = 1-grid[i][j];
  }

  cout << H << " " << W << '\n';
  REP(i, H){
    REP(j, W){
      ll val = grid[i][j];
      if (val==1) cout << '#';
      else        cout << '.';
    }
    cout << '\n';
  }
}


