inline void add(int x,int y){
	for(int i=-1;i<=1;++i){
		for(int j=-1;j<=1;++j)
			G[x+i][y+j]='#';
	}
	G[x][y]='.';
}

inline void build(int cnt){
	for(int i=3;i<=98;i+=4){
		for(int j=3;j<=98;j+=4){
			p[++blk]=(point){i,j};
			add(i,j);
			if(--cnt==0){
				lasti=i,lastj=j;
				return;
			}
		}
	}
}

inline void deal_more(){
	int dta=blkcnt+1-whtcnt;
	if(dta>0){
		for(int i=1;i<=dta;++i)
			G[p[i].x][p[i].y]='#';
	}
	else if(dta<0){
		lasti+=4,lastj+=4;
		int tmp=0;
		for(int j=lastj;j<=98;j+=4){
			p[++blk]=(point){lasti-4,j};
			add(lasti-4,j);
			++tmp;
			if(++dta==0){
				break;
			}
		}
		if(dta<0){
			for(int i=lasti;i<=98;i+=4){
				for(int j=3;j<=98;j+=4){
					p[++blk]=(point){i,j};
					add(i,j);
					++tmp;
					if(++dta==0){
						goto nex;
					}
				}
			}
			nex:;
		}
		for(int i=3;i<=95;i+=4){
			for(int j=3;j<95;j+=4){
				G[i][j+2]='#';
				if(--tmp==0) return;
			}
			G[i+2][3]='#';
			if(--tmp==0) return;
		}
	}
}

inline void rev(){
	for(int i=1;i<=100;++i){
		for(int j=1;j<=100;++j){
			if(G[i][j]=='#') G[i][j]='.';
			else G[i][j]='#';
		}
	}
}

