bool dfs(int v){
	/*
	https://mathtrain.jp/bipartitematching
	未マッチ辺・マッチ辺・未マッチ辺
	これを
	マッチ辺・未マッチ辺・マッチ辺
	に変えると
	1マッチが2マッチになる。
	未[済未]
	増加路を求めている。
	*/
	used[v] = true;//dfsのroot前に初期化される
	int size = G[v].size();
	for(int i=0;i<size;++i){
		int u = G[v][i];//
		int w = match[u];//
		if( w<0 || ((used[w]==false) && dfs(w)) ){
			/*
			マッチングされていない||
			使われてない&&
			*/
			match[v] = u;
			match[u] = v;
			return true;
		}
	}
	return false;
}

int bipartite_matching(){
	int res = 0;
	match = vector<int>(V,-1);//未マッチ状態に初期化
	for(int v=0;v<V;++v){
		if( match[v] < 0 ){
			used = vector<bool>(V,false);
			if( dfs(v) ){
				++res;
			}
		}
	}
	return res;
}
}
