    for (int i = 0; i < HALF_SIZE; i++)
    {
        for (int j = 0; j < HALF_SIZE; j++)
        {
            field[i][j] = true;
        }
    }
    A--;
    B--;

    int h, w;

    h = 0;
    w = 0;
    while (A > 0)
    {
        field[h][w] = false;
        w += 2;
        if (w >= HALF_SIZE)
        {
            h += 2;
            w = 0;
        }
        A--;
    }

    h = 0;
    w = HALF_SIZE + 1;
    while (B > 0)
    {
        field[h][w] = true;
        w += 2;
        if (w >= SIZE)
        {
            h += 2;
            w = HALF_SIZE + 1;
        }
        B--;
    }

    for (int i = 0; i < SIZE; i++)
    {
        for (int j = 0; j < SIZE; j++)
        {
            if (field[i][j])
            {
                cout << '#';
            }
            else
            {
                cout << '.';
            }
        }
        cout << endl;
    }
}

