const int N = 100 + 5;
const int M = 100;

int a, b;
char c[N][N];

void solve()
{
    cin >> a >> b;
    for(int i = 0; i < M; ++ i) {
        c[0][i] = '.';
        c[M - 1][i] = '#';
        for(int j = 1; j < M - 1; ++ j) {
            if (i & 1) {
                c[j][i] = '#';
            } else {
                c[j][i] = '.';
            }
        }
    }
    for(int j = 0; a > 1; j += 2) {
        for(int i = M - 3; a > 1 && i > 1; i -= 2) {
            a--;
            c[i][j] = '#';
        }
    }

    for(int j = M - 1; b > 1; j -= 2) {
        for(int i = 2; b > 1 && i < M - 2; i += 2) {
            --b;
            c[i][j] = '.';
        }
    }
    for(int i = 0; i < M; ++ i) {
        puts(c[i]);
    }
}

int main()
{
    solve();
    return 0;
}

