  cin.tie(0);
  int a, b;
  cin >> a >> b;
  bool flip = false;
  if (a < b) {
    swap(a, b);
    flip = true;
  }
  int h = 100, w = 100;
  vector<VI> ans(h, VI(w, 0));
  int hf = w / 2;
  int pos = 0;
  REP(i, 0, h) {
    REP(j, 0, w) {
      ans[i][j] = i >= h / 2 ? 1 : 0;
    }
  }
  //DEBUGP(hf);
  //DEBUGP(dr);
  while (pos < a - 1) {
    ans[h / 2 + 1 + 2 * (pos / hf)][2 * (pos % hf)] = 0;
