  }
  pos = 0;
  while (pos < b - 1) {
    ans[2 * (pos / hf)][2 * (pos % hf)] = 1;
    pos++;
  }

  if (flip) {
    REP(i, 0, h) {
      REP(j, 0, w) {
	ans[i][j] = 1 - ans[i][j];
      }
