void solve(istream &in, ostream &out) {
    auto a = next<int>(in);
    auto b = next<int>(in);
    vector<string> f(100);
    string tmp = "";
    FOR(i, 100) {
        tmp.push_back('.');
    }
    FOR(i, 100) {
        f[i] = tmp;
    }
    FOR(i, 100) {
        f[i][99] = '#';
    }
    --a;
    for (int row = 3; a && row < 99; row += 4, a--) {
        FOR(i, 100) {
            f[row][i] = '#';
        }
    }
    while (a) {
        for (int col = 3; a && col < 99; col += 4) {
            for (int row = 0; a && row < 99; row += 4) {
                int to_row = max(row + 4, 99);
                for (int j = row; j <= to_row; ++j) {
                    f[j][col] = '#';
                }
                --a;
            }
        }
    }
    --b;

    for (int r = 1; b && r < 99; r += 4) {
        for (int c = 13; b && c < 99; c += 2, --b) {
            f[r][c] = '#';
        }
    }
    out << "100 100\n";
    for (auto ff : f) {
        out << ff << "\n";
    }
}

