  ios::sync_with_stdio(false);
  cout << fixed << setprecision(12);

  int A, B;
  cin >> A >> B;
  int k = 50;
  vector<string> v(2 * k);
  string b, w;
  loop(2 * k) {
    b += "#";
    w += ".";
  }
  rep(i, 0, k) {
    v[i] = b;
    v[i + k] = w;
  }
  auto inrange = [&](int x, int y) {
    return 0 <= x and x < k and 0 <= y and y < 2 * k;
  };

  int dx[] = {1, 0, -1, 0}, dy[] = {0, 1, 0, -1};
  mt19937 rnd(0);

  int cnt = 0;
  while (cnt < A - 1) {
    int x = rnd() % (k - 1), y = rnd() % (2 * k);

    if (v[x][y] == '.')
      continue;

    bool f = true;
    rep(k, 0, 4) {
      int X = x + dx[k], Y = y + dy[k];
      if (inrange(X, Y)) {
        f &= (v[X][Y] == v[x][y]);
      }
    }

    if (f)
      v[x][y] = '.', cnt++;
  }

  auto inrange2 = [&](int x, int y) {
    return k <= x and x < 2 * k and 0 <= y and y < 2 * k;
  };
  cnt = 0;
  while (cnt < B - 1) {
    int x = 1 + rnd() % (k - 1) + k, y = rnd() % (2 * k);

    if (v[x][y] == '#')
      continue;
    bool f = true;
    rep(k, 0, 4) {
      int X = x + dx[k], Y = y + dy[k];
      if (inrange2(X, Y)) {
        f &= (v[X][Y] == v[x][y]);
      }
    }

    if (f)
      v[x][y] = '#', cnt++;
  }

  cout << 2 * k << " " << 2 * k << endl;
  rep(i, 0, v.size()) cout << v[i] << endl;

  return 0;
}

