i64 A;
i64 B;

char ans[100][100];

void put_blacks(i64 n, i64 y) {
    i64 x = 0;
    while(n > 0) {
        ans[y][x] = '#';
        --n;

        x += 2;
        if(x >= 100) {
            x  = 0;
            y += 2;
        }
    }
}

void put_black_row(i64 y) {
    REP(x, 100) {
        ans[y][x] = '#';
    }
}

void solve() {
    ARRAY_FILL(ans, '.');

    i64 ka = 1;
    i64 kb = 0;

    i64 x, y;
    for(y = 1; y < 100; y += 2) {
        for(x = 1; x < 100; x += 2) {
            if(ka == A) goto finish_white;

            ans[y  ][x  ] = '#';
            ans[y-1][x  ] = '#';
            ans[y  ][x-1] = '#';
            ++ka;
            kb = 1;
        }
    }
finish_white: ;

    y += 2;
    put_blacks(B-kb, y);

    PRINTLN(100, 100);
    REP(yy, 100) {
        REP(xx, 100) {
            PRINT(ans[yy][xx]);
        }
        PRINTLN();
    }
}

signed main(signed /*argc*/, char** /*argv*/) {
    RD(A);
    RD(B);



    solve();

    EXIT();
}

