    wc = bc = 1;
    P wcor[2], bcor[2];
    wcor[0] = P{0, 0};
    wcor[1] = P{0, 49};
    bcor[0] = P{0, 99};
    bcor[1] = P{0, 50};
    while (wc < a || bc < b)
    {
        if (bc == b)
        {
            swap(ans[wcor[1].second][wcor[1].first], ans[bcor[0].second][bcor[0].first]);
            if (wcor[1].first + 1 >= 100)
            {
                wcor[1] = P{0, wcor[0].second - 1};
            }
            else
            {
                wcor[1].first += 1;
            }
            bcor[1] = P{wcor[1].first, wcor[1].second + 1};
            if (bcor[0].first + 2 >= 100)
            {
                bcor[0] = (bcor[0].first & 1 ? P{0, bcor[0].second - 1} : P{1, bcor[0].second - 1});
            }
            else
            {
                bcor[0].first += 2;
            }
            ++wc;
        }
        else if (wc == a)
        {
            swap(ans[wcor[0].second][wcor[0].first], ans[bcor[1].second][bcor[1].first]);
            if (wcor[1].first + 1 >= 100)
            {
                bcor[1] = P{0, bcor[0].second + 1};
            }
            else
            {
