            if (wcor[0].first + 2 >= 100)
            {
                wcor[0] = (wcor[0].first & 1 ? P{0, wcor[0].second + 1} : P{1, wcor[0].second + 1});
            }
            else
            {
                wcor[0].first += 2;
            }
            ++bc;
        }
        else
        {
            swap(ans[wcor[0].second][wcor[0].first], ans[bcor[0].second][bcor[0].first]);
            if (wcor[0].first + 2 >= 100)
            {
                wcor[0] = (wcor[0].first & 1 ? P{0, wcor[0].second + 1} : P{1, wcor[0].second + 1});
            }
            else
            {
                wcor[0].first += 2;
            }
            if (bcor[0].first + 2 >= 100)
            {
                bcor[0] = (bcor[0].first & 1 ? P{0, bcor[0].second - 1} : P{1, bcor[0].second - 1});
            }
            else
            {
                bcor[0].first += 2;
            }
            ++wc, ++bc;
        }
    }

    cout << "100 100\n";
    rep (i, 100)
    {
        cout << ans[i] << "\n";
    }

