			ans[3 * i + 1][3 * j + 1] = '#';
			j += dir;
			if (j >= 33) { j = 32; dir = -1; i++; }
			else if (j < 0) { j = 0; dir = 1; i++; }
			cnt++;
		}
	}

	else if (B == 1) {
		for (i = 0; i < 100; i++) for (j = 0; j < 100; j++) ans[i][j] = '#';
		i = 0; j = 0; int cnt = 0, dir = 1;
		while (cnt < A) {
			for (k = 0; k < 3; k++) for (l = 0; l < 3; l++) ans[3 * i + k][3 * j + l] = '#';
			ans[3 * i + 1][3 * j + 1] = '.';
			j += dir;
			if (j >= 33) { j = 32; dir = -1; i++; }
			else if (j < 0) { j = 0; dir = 1; i++; }
			cnt++;
		}
	}

	else {
		//A' = 1, B' = B - 1のスネーク
		for (i = 0; i < 100; i++) for (j = 0; j < 100; j++) ans[i][j] = '.';
		i = 0; j = 0; int cnt = 0, dir = 1;
		while (cnt < B - 1) {
			for (k = 0; k < 3; k++) for (l = 0; l < 3; l++) ans[3 * i + k][3 * j + l] = '.';
			for (k = 0; k < 3; k++) for (l = 0; l < 3; l++) isMark[3 * i + k][3 * j + l] = true;
			ans[3 * i + 1][3 * j + 1] = '#';
			j += dir;
			if (j >= 33) { j = 32; dir = -1; i++; }
			else if (j < 0) { j = 0; dir = 1; i++; }
			cnt++;
		}

		//A' = A - 1, B' = 1のスネーク
		for (int ii = 0; ii < 100; ii++) for (int jj = 0; jj < 100; jj++) if (!isMark[ii][jj]) ans[ii][jj] = '#';
		cnt = 0;
		while (cnt < A - 1) {
			for (k = 0; k < 3; k++) for (l = 0; l < 3; l++) ans[3 * i + k][3 * j + l] = '#';
			ans[3 * i + 1][3 * j + 1] = '.';
			j += dir;
			if (j >= 33) { j = 32; dir = -1; i++; }
			else if (j < 0) { j = 0; dir = 1; i++; }
			cnt++;
		}
	}

	cout << 100 << " " << 100 << endl;
	for (i = 0; i < 100; i++) {
		for (j = 0; j < 100; j++) {
			cout << ans[i][j];
		}
		cout << endl;
	}
	return 0;
}

