bool ta[101][101];
int step1(int gre, int less) {

	less--;

	int col = 0;
	while (gre > less)
	{
		for (size_t i = 0; i < 100 && gre > less; i += 2)
		{
			ta[i][col] = true;
			gre--;
		}
		col += 2;
	}
	return col;
}

void step2(int v,int start) {

	int len = (100 - start);
	int half = len / 2;
	for (size_t i = 0; i < 100; i++)
	{
		for (size_t j = start; j < start + half; j++)
		{
			ta[i][j] = true;
		}
	}
	v--;
	if (v == 0) return;
	for (size_t i = 0; i < 100; i += 2)
	{
		ta[i][start + half - 1] = false;
		ta[i][start + half] = true;
		v--;
		if (v == 0) return;
	}

	bool even = true;
	int c = 1;
	while (v > 0)
	{
		// 右側から
		for (size_t i = even; i < 100; i += 2)
		{
			ta[i][start + half + c] = true;
			v--;
			if (v == 0) return;
		}

		for (size_t i = even; i < 100; i += 2)
		{

			ta[i][start + half - 1 - c] = false;
			v--;
			if (v == 0) return;
		}
		c++;
		even = !even;
	}
}
