		step2(less - (start > 0), start);
	}

	cout << 100 << " " << 100 << endl;
	for (size_t i = 0; i < 100; i++)
	{
		string res = "";
		for (size_t j = 0; j < 100; j++)
		{
			res += (a == gre) ? ta[i][j] ? "." : "#"
				: ta[i][j] ? "#" : ".";
		}
		cout << res << endl;
	}
}


