#include <bits/stdc++.h>
int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  constexpr size_t mx = 100;
  std::array<std::array<bool, mx>, mx> grd = {};
  for (size_t i = 1; i < mx - 1; i++) {
    for (size_t j = 1; j < mx; j += 2) {
      grd.at(i).at(j) = true;
    } 
  }
  for (size_t j = 0; j < mx; j++) {
    grd.at(mx - 1).at(j) = true;
  }
  auto punch = [&] (int k) {
    assert(k >= 0);
    if (k == 0) return;
    for (size_t j = 0; j < mx; j += 2) {
      for (size_t i = 1; i < mx - 1; i += 2) {
        grd.at(i).at(j) ^= 1;
        k--;
        if (k == 0) break;
      }
      if (k == 0) break;
    }
  };
  auto transpose = [&] {
    std::array<std::array<bool, mx>, mx> new_grd = {};
    for (size_t i = 0; i < mx; i++) {
      for (size_t j = 0; j < mx; j++) {
        new_grd.at(i).at(j) = grd.at(mx - 1 - i).at(mx - 1 - j);
      }
    }
    grd = new_grd;
  };
  int a, b; std::cin >> a >> b;
  punch(a - 1); transpose();
  punch(b - 1); transpose();
  std::cout << mx << " " << mx << std::endl;
  for (size_t i = 0; i < mx; i++) {
    for (size_t j = 0; j < mx; j++) {
      std::cout << (grd.at(i).at(j) ? "#" : ".");
    }
    std::cout << std::endl;
  }
  return 0;
}

