	}
}
int main()
{
	int a, b;
	scanf("%d%d", &a, &b);
	--a; --b;
	for(int i = 1; i < n; ++i)
		for(int j = 1; j <= n; ++j)
			if(i == 1 || j & 1)
				col[i][j] = 1;
	for(int j = 2; a > 0; j += 2)
		for(int i = 3; i < n && a > 0; i += 2)
		{
			col[i][j] ^= 1; 
			--a;
		}
	for(int j = n - 1; b > 0; j -= 2)
		for(int i = n - 2; i > 1 && b > 0; i -= 2)
		{
			col[i][j] ^= 1;
			--b;
		}
	output();
	return 0;
}

