vl ans;
void dfs(int v, int p=-1, int c=-1){
  int k=1;
  for(auto nv:G[v]){
    int next=nv.first,id=nv.second;
    if(next==p)continue;
    if(k==c)k++;
    ans[id]=k;
    k++;
    dfs(next,v,ans[id]);
  }
}


