void solve() {
    int cnt[2] = {0, 0};
    for (int i = 0; i < H; i++) {
        int p = i / (H / 2);
        for (int j = 0; j < W; j++) {
            int q = ((i - p * (H / 2)) % 2) * (j % 2);
            cnt[p] += q;
            int r = (cnt[p] <= AB[p] - 1) ? 1 : 0;
            ans[i][j] = wb[(p + q * r + 1) % 2];
        }
    }
}

