			if (ans[i][j] == '#') {
				ans[i][j] = '.';
			}
			rest--;
			if (rest == 0) return;
		}
		i += 4;
	} else {
		for (int j = 1; j < w; j += 2) {
			if (ans[i - 1][j] == '#') {
				ans[i - 1][j] = '.';
			}

			if (ans[i][j] == '#') {
				ans[i][j] = '.';
			}
			rest--;
			if (rest == 0) return;
		}
	}



	for (; i <= h; i += 4) {
		for (int j = 0; j < w; j += 2) {
