vector<string> solve(int n) {
  vector<string> res;
  int p = n / 50;
  int r = n % 50;
  string kuro = "";
  string tmp = "";
  for (int i = 0; i < 100; ++i) kuro += "#";
  for (int i = 0; i < p; ++i) {
	res.push_back(kuro);
	tmp = "";
	for (int j = 0; j < 100; ++j) {
	  if (j % 2 == 0) tmp += '.';
	  else tmp += '#';
	}
	res.push_back(tmp);
  }
  res.push_back(kuro);
  tmp = "";
  for (int i = 0; i < r*2; ++i) {
	if (i % 2 == 0) tmp += '.';
	else tmp += '#';
  }
  while (tmp.size() < 100) tmp += '#';
  res.push_back(tmp);
  res.push_back(kuro);

  return res;
}

void rev(vector<string> &vec) {
  for (int i = 0; i < vec.size(); ++i) {
	for (int j = 0; j < vec[i].size(); ++j) {
	  if (vec[i][j] == '.') vec[i][j] = '#';
	  else vec[i][j] = '.';
	}
  }
}


