// Union-Find 木 (Verified: AtCoder Typical Contest 001 B)
struct UnionFind {
private:
    const int n;
    int __size;
    vector<int> uf;
public:
    // 初期化 UnionFind uni(n) のように宣言すれば良い
    UnionFind(int _n) : n(_n), __size(_n), uf(_n, -1) {}
    // find (木の根を求める)
    int find(int x) {return (uf[x] < 0) ? x : uf[x] = find(uf[x]);}
    // x と y が同じ集合に属するかどうか
    bool same(int x, int y) {return find(x) == find(y);}
    // x が属する集合の要素数
    int size(int x) {return -uf[find(x)];}
    // 集合はいくつあるか
    int size()      {return __size;}
    // x と y の属する集合を併合
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if(x == y) return;
        __size--;
        if(uf[y] < uf[x]) swap(x, y);
        uf[x] += uf[y]; uf[y] = x;
    }
};

char board[110][110];
const char WHITE = '.', BLACK = '#';
const int H = 100, W = 100;

signed main() {
    int A, B; cin >> A >> B;
    for(int i=0; i<H/2; i++) {
        for(int j=0; j<W; j++) {
            board[i][j] = WHITE;
            if(i%2 == 0 && j%2 == 0) {
                if(B > 1) {
                    board[i][j] = BLACK;
                    B--;
                }
            }
        }
    }
    for(int i=H-1; i>=H/2; i--) {
        for(int j=0; j<W; j++) {
            board[i][j] = BLACK;
            if(i%2 == 0 && j%2 == 0) {
                if(A > 1) {
                    board[i][j] = WHITE;
                    A--;
                }
            }
        }
    }

    for(int i=0; i<H; i++) {
        for(int j=0; j<W; j++) {
            printf("%c", board[i][j]);
        }
        printf("\n");
    }
    return 0;
}

