using namespace std;

const int maxr = 96;
const int maxc = 100;

char a[maxr][maxc];
int main()
{
    int A, B;
    scanf("%d%d", &A, &B);

    int mx = min(16, min(A, B)), tempA = A, tempB = B, cnt = 0;
    for(int i = 0; i < maxr; i ++) {
        if(i % 6 == 0)
            tempA --;
        if(i % 6 == 3)
            tempB --;
        if(i % 6 == 2) {
            cnt ++;
            if(cnt == mx) {
                if(A < B) {
                    for(int k = i; k < maxr; k ++)
                        for(int j = 0; j < maxc; j ++)
                            a[k][j] = '.';
                } else {
                    tempB --;
                    for(int k = i; k < maxr; k ++)
                        for(int j = 0; j < maxc; j ++)
                            a[k][j] = '#';
                }
                break;
            }
        }
        for(int j = 0; j < 100; j ++) {
            if((i % 6 ) <= 2)
                a[i][j] = '.';
            if((i % 6) > 2)
                a[i][j] = '#';
        }
    }

    int resW = tempA, resB = tempB;
    for(int i = 1; i < maxr; ) {
        if((i % 6) == 1) {
            for(int j = 0; j < maxc; j += 2)
                if(resB)
                    resB --, a[i][j] = '#';
        } else {
            for(int j = 0; j < maxc; j += 2)
                if(resW)
                    resW --, a[i][j] = '.';
        }
        i += 3;
    }
    int row = maxr;
    printf("%d %d\n", row, 100);
    for(int i = 0; i < row; i ++) {
        for(int j = 0; j < maxc; j ++)
            printf("%c", a[i][j]);
        puts("");
    }
    return 0;
}

