int main () {
    scanf("%d%d", &A, &B);
    if (A == 1 && B == 1) {
        ++h;
        for (int i = 1; i <= w; i++) {
            if (i == 1) {
                m[h][i] = '#';
            } else m[h][i] = '.';
        }
    } else {
        if (A == 1 && B > 1) swap(A, B);
        ++ h;
        for (int i = 1; i <= w; i++) m[h][i] = '#';
        -- B;
        int t = A/49, y = A%49;
        while (t--) {
            ++h;
            for (int i = 2; i <= w; i+=2) {
                if ((i/2) <= 49) m[h][i] = '.';
            }
            for (int i = 1; i <= w; i++) {
                if (!m[h][i]) m[h][i] = '#';
            }
            ++ h;
            for (int i = 1; i <= w; i++) m[h][i] = '#';
        }
        {
            ++h;
            for (int i = 2; i <= w; i+=2) {
                if ((i/2) <= y) m[h][i] = '.';
            }
            for (int i = 1; i <= w; i++) {
                if (!m[h][i]) m[h][i] = '#';
            }
            ++ h;
            for (int i = 1; i <= w; i++) m[h][i] = '#';
