        for (int j = n / 2 + 2; j <= n; ++j) {
            if (0 == a) {
                break;
            }
            if (j % 2 == 1) {
                ans[curRow][j] = 0;
                --a;
            }
        }
        curRow += 2;
    }
    printf("%d %d\n", n, n);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (ans[i][j] == 1) {
