      if(nx < 0 || ny < 0 || nx >= w || ny >= h || mp[ny][nx] != col) continue;
      dfs(nx,ny,col);
    }
  };

  int cntA = 0,cntB = 0;
  for(int i=0;i < h;i++)
    for(int j=0;j < w;j++){
      if(mp[i][j] == '!') continue;
      mp[i][j] == '.'? cntA++:cntB++;
      dfs(j,i,mp[i][j]);
    }

  return cntA == A && cntB == B;
}

vector<string> solve(int A,int B){

  int K = 50;
  vector<string> mp(K*2);

  for(int i=0;i<K;i++) mp[i] = string(K*2,'#');
  for(int i=0;i<K;i++) mp[K+i] = string(K*2,'.');

  {  
    int a = 1;
    for(int i=0;i<K;i+=2)
      for(int j=0;j<K*2;j+=2){
        if(A == a) continue;
        a++;
        mp[i][j] = '.';
      }
  }

  {
    int b = 1;
    for(int i=0;i<K;i+=2)
      for(int j=0;j<K*2;j+=2){
        if(B == b) continue;
        b++;
        mp[K+i+1][j] = '#';
      }
  }
  return mp;
}


