lint pow(lint num, lint e, lint MOD) {
    lint res = 1;
    lint cur_num = num;
    while (e) {
        if (e & 1) {
            res *= cur_num;
            res %= MOD;
        }
        cur_num *= cur_num;
        cur_num %= MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    cin.tie(0); cout.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);
    lint A, B; cin >> A >> B;
    const char WHITE = '.', BLACK = '#';
    lint h = 100, w = 100;
    vec<string> grid(h, string(w / 2, '.').append(string(w / 2, '#')));
    // init
    grid.at(0) = string(w, '.');
    grid.at(h - 1) = string(w, '#');
    auto fill_col = [](vec<string>& grid, lint col, char color) {
        lint h = grid.size();
        range(i, 0, h) grid.at(i).at(col) = color;
        return;
    };
    auto fill_row = [](vec<string>& grid, lint row, lint l, lint r, char color) {
        range(j, l, r) grid.at(row).at(j) = color;
    };

    // increase num whites
    range(i, 0, min(h / 2 - 1, A - 1)) {
        lint row = 1 + i * 2;
        fill_row(grid, row, 0, w / 2, BLACK);
    }
    if (A > h / 2) {
        lint remaining_A = A - h / 2;
        remaining_A += max(0LL, min(B - h / 2 - 1, 49LL));
        lint col = 1, row = 0;
        while (remaining_A) {
            grid.at(row).at(col) = BLACK;
            if (row == h - 2) {
                row = 0; col += 2;
            } else row += 2;
            remaining_A -= 1;
        }
    }

    // increase num blacks
    range(i, 0, min(h / 2 - 1, B - 1)) {
        lint row = 2 + i * 2;
        fill_row(grid, row, w / 2, w, WHITE);
    }
    if (B > h / 2) {
        lint remaining_B = B - h / 2;
        remaining_B += max(0LL, min(A - h / 2 - 1, 49LL));
        lint col = w / 2 + 1, row = 1;
        while (remaining_B) {
            grid.at(row).at(col) = WHITE;
            if (row == h - 1) {
                row = 1; col += 2;
            } else row += 2;
            remaining_B -= 1;
        }
    }
    auto num_components = [](const vec<string>& grid) {
        lint num_whites = 0, num_blacks = 0;
        lint h = grid.size(), w = grid.at(0).size();
        vec<vec<bool>> visited(h, vec<bool>(w, false));
        vec<lint> dy = {-1, 1, 0, 0}, dx = {0, 0, -1, 1};
        function<void(lint, lint, char)> dfs = [&](lint y, lint x, char color) {
            range(k, 0, 4) {
                lint ny = y + dy.at(k), nx = x + dx.at(k);
                if (ny < 0 or ny >= h or nx < 0 or nx >= w) continue;
                else if (visited.at(ny).at(nx)) continue;
                else if (grid.at(ny).at(nx) != color) continue;
                else {
                    visited.at(ny).at(nx) = true;
                    dfs(ny, nx, color);
                }
            }
            return;
        };
        range(y, 0, h) range(x, 0, w) {
            if (!visited.at(y).at(x)) {
                if (grid.at(y).at(x) == '.') num_whites += 1;
                else num_blacks += 1;
                visited.at(y).at(x) = true;
                dfs(y, x, grid.at(y).at(x));
            }
        }
        return make_pair(num_whites, num_blacks);
    };
    plint nums = num_components(grid);
    // cout << nums << "\n";
    assert(nums.first == A);
    assert(nums.second == B);
    cout << h << " " << w << "\n";
    range(y, 0, h) cout << grid.at(y) << "\n";
}

