#define REP(i, n) for (int i = 0; (i) < int(n); ++ (i))
using namespace std;

constexpr int height = 100;
constexpr int width = 100;
array<array<bool, width>, height> solve(int a, int b) {
    array<array<bool, width>, height> f = {};
    REP (y, height / 2) {
        REP (x, width) {
            f[y][x] = true;
        }
    }
    for (int y = 0; y < height / 2; y += 2) {
        for (int x = 0; x < width; x += 2) {
            if (a >= 2) {
                a -= 1;
                f[y][x] = false;
            }
        }
    }
    for (int y = height - 1; y >= height / 2; y -= 2) {
        for (int x = 0; x < width; x += 2) {
            if (b >= 2) {
                b -= 1;
                f[y][x] = true;
            }
        }
    }
    return f;
}

int main() {
    int a, b; scanf("%d%d", &a, &b);
    array<array<bool, width>, height> f = solve(a, b);
    printf("%d %d\n", height, width);
    REP (y, height) {
        REP (x, width) {
            printf("%c", f[y][x] ? '#' : '.');
        }
        printf("\n");
    }
    return 0;
}

