int board[100][100];
int dx[4] = {-1,0,1,0};
int dy[4] = {0,-1,0,1};

void clear() {
	for (int i = 0; i<100; ++i) {
		for (int j = 0; j<100; ++j) {
			board[i][j] = (j%2 != 0);
		}
	}
}

vector<int> check() {
	vector<int> res;
	res.pb(0);
	res.pb(0);
	bool used[100][100];
	for (int i = 0; i<100; ++i) {
		for (int j = 0; j<100; ++j) {
			used[i][j] = 0;
		}
	}
	for (int i = 0; i<100; ++i) {
		for (int j = 0; j<100; ++j) {
			int type = board[i][j];
			if (!used[i][j]) {
				res[type]++;
				used[i][j] = 1;
				queue<pair<int, int>> q;
				q.push(mp(i,j));
				while (!q.empty()) {
					pair<int, int> cur = q.front();
					q.pop();
					for (int i = 0; i<4; ++i) {
						int nx = cur.first + dx[i];
						int ny = cur.second + dy[i];
						if (nx >= 0 && nx < 100 && ny >= 0 && ny < 100 && !used[nx][ny] && board[nx][ny] == type) {
							used[nx][ny] = 1;
							q.push(mp(nx,ny));
						}
					}
				}
			}
		}
	}
	return res;
}

int solve(int x, int y) {
	int w = 50, b = 50;
	int lx = 3, ly = 0, rx = 3, ry = 99;
	int ld = 1, rd = 98;
	while (w != x || b != y) {
		if (w < x) {
			board[lx][ly] = 1;
			lx += 2;
			w++;
			if (lx == 5 && ly != 0) {
				b--;
			}
			if (lx == 99) {
				lx = 3;
				ly += 2;
			}
		}
		if (b < y) {
			board[rx][ry] = 0;
			rx += 2;
			b++;
			if (rx == 5 && ry != 99) {
				w--;
			}
			if (rx == 99) {
				rx = 3;
				ry -= 2;
			}
		}
		if (w > x) {
			board[0][ld] = 0;
			w--;
			ld += 2;
		}
		if (b > y) {
			board[99][rd] = 1;
			b--;
			rd -= 2;
		}
	}
}

