        x = 0;
        y++;
    }
    else {
        x++;
    }
}

vector<string> calc(int a, int b) {
    vector<string> ans(H, string(W, 'x'));
    int tar[2] = {a, b};
    int cnt[2] = {0, 0};
    char ch[2] = {'.', '#'};
    int cur = 0;
    int nxt = 1;
    if(a < b) swap(cur, nxt);

    auto canPut = [&](int y, int x) {
        rep(i, 2) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if(isOutOfRange(ny, nx)) continue;
            if(ans[ny][nx] == ch[cur]) return false;
        }
        return true;
    };
    function<char(int, int)> getAltChar = [&] (int y, int x) {
        rep(i, 2) {
            if(ans[y][x] != ch[i]) return ch[i];
        }
        assert(false);
    };
    function<char(int, int)> getEndPut = [&](int y, int x) {
        if(y == 0 && x == 0) assert(false);
        if(y == 0) return ans[y][x-1];
        if(x == 0) return ans[y-1][x];
        if(ans[y-1][x] == ans[y][x-1]) return getAltChar(y-1, x);
        return ans[y-1][x];
    };

    int y = 0, x = 0;
    while(y < H && x < W) {
        dump(ans[0]);
        dump(ch[cur]);
        if(cnt[cur] < tar[cur]) {
            while(canPut(y, x) == false && isOutOfRange(y, x) == false) {
                ans[y][x] = ch[nxt];
                getNxtXY(y, x);
                // dump(mp(y, x));
            }
            ans[y][x] = ch[cur];
            getNxtXY(y, x);
            cnt[cur]++;
        }
        else if(cnt[cur] == tar[cur] && cnt[nxt] == tar[nxt] ){
            if(x == 0) {
                ans.resize(y);
                break;
            }
            ans.resize(y+1);
            ans[y][x] = getEndPut(y, x);
            getNxtXY(y, x);
            if(x == 0) break;
            while(x < W) {
                if(y > 0)ans[y][x] = ans[y-1][x];
                else ans[y][x] = ans[y][x-1];
                ++x;
            }
            break;
        }
        swap(cur, nxt);
    }
    return ans;
}

int main() {
    int a, b;
    cin >> a >> b;

    auto ans = calc(a, b);

    cout << ans.size() << " " << ans[0].size() << endl;
    rep(i, ans.size()) {
        cout << ans[i] << endl;
    }
    return 0;
}

