    if (y < 0 or y >= H or x < 0 or x >= W)
    {
        return true;
    }
    return false;
}
int get_idx(int y, int x, int W)
{
    return y * W + x;
}
pii get_position(int idx, int W)
{
    int y = idx / W;
    int x = idx % W;
    return mp(y, x);
}
bool solve(const int H, const int W)
{
    int a = 0;
    int b = 0;

    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            if ((i + j) % 2 == 0)
            {
                a++;
                board[i][j] = '.';
            }
            else
            {
                b++;
                board[i][j] = '#';
            }
        }
    }
    // print_board(H, W);
    // return ;
    UnionFind ut(H * W);
    int cnt = 0;
    bool ans = true;
    while (a > A)
    {
        vector<pair<int, pii>> costs;
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                if (board[i][j] == '#')
                {
                    continue;
                }
                vector<int> neighbors;
                for (int k = 0; k < 4; k++)
                {
                    int ny = i + dy[k];
                    int nx = j + dx[k];
                    if (is_over(ny, nx, H, W))
                    {
                        continue;
                    }
                    if (board[ny][nx] == '#')
                    {
                        neighbors.push_back(get_idx(ny, nx, W));
                    }
                }

                if (!neighbors.empty())
                {
                    int cost = neighbors.size() - 1;
                    for (int i = 0; i < neighbors.size(); i++)
                    {
                        for (int j = i + 1; j < neighbors.size(); j++)
                        {
                            if (ut.is_same(neighbors[i], neighbors[j]))
                            {
                                cost--;
                                break;
                            }
                        }
                    }
                    costs.push_back(mp(cost, mp(i, j)));
                }
            }
        }
        sort(costs.begin(), costs.end());
        bool ok = false;
        for (const auto &val : costs)
        {
            int cost = val.first;
            pii pos = val.second;
            int y = pos.first;
            int x = pos.second;
            if (b - cost >= B)
            {
                b -= cost;
                a--;
                board[y][x] = '#';
                for (int k = 0; k < 4; k++)
                {
                    int ny = y + dy[k];
                    int nx = x + dx[k];
                    if (is_over(ny, nx, H, W))
                    {
                        continue;
                    }
                    if (board[ny][nx] == '#')
                    {
                        ut.unite(y * W + x, ny * W + nx);
                    }
                }
                ok = true;
                break;
            }
        }
        if (!ok)
        {
            ans = false;
            break;
        }
    }
    if (!(a == A and b == B))
    {
        ans = false;
    }
    // cerr << a << " " << b << endl;
    if (ans)
    {
        print_board(H, W);
    }
    return ans;
}
