void Build(){
	int C=B-A;
	int n=B*2;
	//mmp 1ÉÙ 0¶à

	for (int h=100;h>=0;h--){
		if (n%h==0){
			int w=n/h;
			if (w%2) swap(h,w);
			t1=h,t2=w;
			for (int i=1;i<=h;i++)
			for (int j=1;j<=w;j++)
			if ((i&1)&&(j&1)||!(i&1)&&!(j&1)) mmp[i][j]=1;
			break;
		}
	}
	C++;
	for (int i=1;i<=t1;i++){
		if (C){
			if (mmp[i][1]) C--;
			mmp[i][0]=1;
		}
		else mmp[i][0]=mmp[i][1];
	}
	//cout<<"Left Wipe Finished."<<C<<endl;
	if (C){
		C++,t2++;
		for (int i=1;i<=t1;i++){
			if (C){
				if (mmp[i][t2-1]) C--;
				mmp[i][t2]=1;
			}
			else mmp[i][t2]=mmp[i][t2-1];
		}
