		for (int i=0;i<=t2;i++)
		if (C){
			if (mmp[1][i]) C--;
			mmp[0][i]=1;
		}
		else mmp[0][i]=mmp[1][i]; 
		if (mmp[1][t2-1]==1&&mmp[1][t2]==1) C--;
	}
	//cout<<"Above Wipe Finished."<<C<<endl;
	if (C){
		C+=2,t1++;
		for (int i=0;i<=t2;i++)
		if (C){
			if (mmp[t1-1][i]) C--;
			mmp[t1][i]=1;
		}
		else mmp[t1][i]=mmp[t1-1][i]; 
		if (mmp[t1][t2-1]==1&&mmp[t1][t2]==1) C--;
	}
	//cout<<"Under Wipe Finished."<<C<<endl;
}
