void solve()
{
      ll a, b;
      cin>>a>>b;
      ll grid[101][101];
      for(ll i=1; i<=50; i++) for(ll j=1; j<=100; j++) grid[i][j]=0;  // white
      for(ll i=51; i<=100; i++) for(ll j=1; j<=100; j++) grid[i][j]=1; // black
      ll ac=1, bc=1;
      swap(a, b);
      ll parity=1;
      for(ll i=1; i<=49; i++)
      {
              for(ll j=1; j<=100; j++)
              {
                     if(ac>=a) break;
                     if(parity) // do black for odd
                     {
                            if(ac<a && j&1) { grid[i][j]=1; ac++; }
                     }
                     else // do black for even
                     {
                            if(ac<a && j%2==0) { grid[i][j]=1; ac++; }
                     }
              }
              if(ac>=a) break;
              parity = 1 - parity;
      }
      parity=1;
      for(ll i=52; i<=100; i++)
      {
             for(ll j=1; j<=100; j++)
             {
                    if(bc >= b) break;
                    if(parity)
                    {
                           if(bc < b && j&1) { grid[i][j] = 0; bc++; }
                    }
                    else
                    {
                           if(bc < b && j%2==0) { grid[i][j]=0; bc++; }
                    }
             }
             if(bc >= b) break;
             parity = 1 - parity;
      }
      rep(i,1,101)
      {
             rep(j,1,101)
             {
                    if(grid[i][j]==1) cout<<"#";
                    else cout<<".";
             }
             cout<<endl;
      }
}


