int main(void) {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int a, b;
  cin >> a >> b;
  bool flip = false;
  if (a < b) {
    swap(a, b);
    flip = true;
  }
  int h = 100, w = 100;
  vector<VI> ans(h, VI(w, 0));
  int hf = w / 2;
  int dr = (b - 1 + hf - 1) / hf;
  int pos = 0;
  //DEBUGP(hf);
  //DEBUGP(dr);
  while (pos < b - 1) {
    int row = (pos / hf) % 2 ? 1 : 0;
    ans[h - dr + pos / hf][2 * (pos % hf) + row] = 1;
    ans[h - dr + pos / hf][2 * (pos % hf) + (1 - row)] = 0;
    pos++;
  }
  REP(i, 0, w) {
    ans[h - dr - 1][i] = 0; // blocked by white
  }
  REP(i, 0, h - dr - 1) {
    REP(j, 0, w) {
      ans[i][j] = 1; // black
    }
  }
  pos = 0;
  int rem = a - b;
  if (dr > 2) {
    rem += hf - 1;
  } else if (dr == 2) {
    rem = a - (b - 1 - hf) - 1;
  } else {
    rem = a - 1;
  }
  while (pos < rem) {
    int row = (pos / hf) % 2 ? 1 : 0;
    ans[2 * (pos / hf)][2 * (pos % hf) + row] = 0;
    pos++;
  }

  if (flip) {
    REP(i, 0, h) {
      REP(j, 0, w) {
	ans[i][j] = 1 - ans[i][j];
      }
    }
  }

  cout << h << " " << w << endl;
  REP(i, 0, h) {
    REP(j, 0, w) {
      cout << (ans[i][j] ? '#' : '.'); 
    }
    cout << endl;
  }
}

