#include "bits/stdc++.h"
using namespace std;
char s[111][111];
const int h = 100;
const int w = 100;
bool vis[111][111];

int inside(int x, int y) {
	return (0 <= x && x < h) && (0 <= y && y < w);
}
const int dx[] = {0, 0, 1, -1};
const int dy[] = {1, -1, 0, 0};

void dfs(int x, int y) {
	vis[x][y] = true;
	for(int i = 0; i < 4; i++) {
		int p = x + dx[i];
		int q = y + dy[i];
		if(inside(p, q) && s[p][q] == s[x][y] && vis[p][q] == false) {
			dfs(p, q);
		}
	}
}

int main(int argc, char const *argv[])
{
	memset(s, '&', sizeof s);
	int A, B;
	cin >> A >> B;
	bool bad = false;
	if(A > B) {
		swap(A, B);
		bad = true;
	}
	A--;
	int cntA = 0;
	int cntB = 0;
	for(int i = 0; i < h; i++) {
		if(A == cntA) {
			for(int j = 0; j < w; j++) {
				s[i][j] = '#';
			}
			break;
		}
		for(int j = 0; j < w; j++) {
			if(A == cntA) {
				for(int k = j; k < w; k++) {
					s[i][k] = '#';
				}
				break;
			}
			if((i + j) % 2 == 0) {
				s[i][j] = '.';
				++cntA;
			} else {
				s[i][j] = '#';
				++cntB;
			}
		}
	}
	for(int i = 0; i < h; i++) {
		for(int j = 0; j < w; j++) {
			if(s[i][j] == '&') {
				s[i][j] = '.';
			}
		}
	}

	int fa = 0;
	int fb = 0;

	for(int i = 0; i < h; i++) {
		for(int j = 0; j < w; j++) {
			if(vis[i][j] == false) {
				dfs(i, j);
				if(s[i][j] == '.') ++fa;
				else ++fb;
			}
		}
	}
	// cout << fa << " " << fb << endl;
	// assert(fa == A);
	for(int i = h-1; i >= 0; i -= 2) {
		if(fb == B) break;
		for(int j = 0; j < w; j += 2) {
			if(fb == B) break;
			s[i][j] = '#';
			++fb;
		}
	} 
	// cout << fb << endl;
	cout << h << " " << w << endl;
	for(int i = 0; i < h; i++) {
		for(int j = 0; j < w; j++) {
			if(bad) s[i][j] = (s[i][j] == '#') ? '.' : '#';
			cout << s[i][j];
		}
		cout << endl;
	}
	return 0;
}

