//A,B共に、16以上の場合
void make_pattern_1()
{
	const int H = 96;
	const int W = 100;
	//init  上から3行はtrue(black)
	REP(i, H) {
		int j = i / 3;
		ans.push_back(vector<bool>(W, (j % 2 == 0)));
	}
	//6行で1セット
	A -= H / 6;
	B -= H / 6;

	//さて、AとBが消えるまで動かしていこうか
	int i = 1;
	int j = 0;
	while (A > 0) {
		ans[i][j] = false;
		j += 2;
		if (j >= 100) {
			i += 6;
			j = 0;
		}
		A--;
	}

	i = 4;
	j = 0;
	while (B > 0) {
		ans[i][j] = true;
		j += 2;
		if (j >= 100) {
			i += 6;
			j = 0;
		}
		B--;
	}
}

//片方が16以下の場合
void make_pattern_2()
{
	//true==black
	const int H = 96;
	const int W = 100;
	if (B <= A) {
		//上から、WWWBBBWWWBBB..  BBBWWWBBBBBBBBBBBBBBB
		REP(i, B) {
			REP(j, 3)ans.push_back(vector<bool>(W, false));
			REP(j, 3)ans.push_back(vector<bool>(W, true));
		}
		while (ans.size() < H) {
			ans.push_back(vector<bool>(W, true));
		}
		A -= B;
		B = 0;
		//あとは埋めるだけ
		int i = 4;
		int j = 0;
		while (A > 0) {
			ans[i][j] = false;
			j += 2;
			if (j >= 100) {
				i += 6;
				j = 0;
			}
			A--;
		}
	}
	else {
		//上から、BBBWWWBBB....BBBWWWBBBWWWWWWWWWWWWW
		REP(i, A) {
			REP(j, 3)ans.push_back(vector<bool>(W, true));
			REP(j, 3)ans.push_back(vector<bool>(W, false));
		}
		while (ans.size() < H) {
			ans.push_back(vector<bool>(W, false));
		}
		B -= A;
		A = 0;
		int i = 4;
		int j = 0;
		while (B > 0) {
			ans[i][j] = true;
			j += 2;
			if (j >= 100) {
				i += 6;
				j = 0;
			}
			B--;
		}
	}
}

//計算
void calc()
{
	if (A >= 16 && B >= 16) {
		make_pattern_1();
	}
	else {
		make_pattern_2();
	}
}


//出力
void output()
{
	cout << "96 100" << endl;
	for (auto row : ans) {
		for (bool col : row) {
			cout << (col ? "#" : ".");
		}
		cout << endl;
	}
}


