const int N = 100;
int T[N][N], A, B;

void solve() {
	A = fetch<int>() - 1;
	B = fetch<int>() - 1;

	for(int i = 0; i < N; ++i) {
		for(int j = 0; j < N; ++j) {
			T[i][j] = (j < N / 2);
		}
	}

	for(int i = 0; i < N; ++i) {
		for(int j = 0; j < N / 2 - 1; ++j) {
			if(i % 3 == 1 && j % 3 == 1 && A > 0) {
				T[i][j] = 0;
				--A;
			}
		}

		for(int j = N / 2; j < N; ++j) {
			if(i % 3 == 1 && (j - N / 2) % 3 == 1 && B > 0) {
				T[i][j] = 1;
				--B;
			}
		}
	}

	cout << N << ' ' << N << '\n';

	for(int i = 0; i < N; ++i) {
		string line(N, '$');

		for(int j = 0; j < N; ++j) {
			line[j] = (T[i][j] ? '#' : '.');
		}

		cout << line << '\n';
	}
}

int main() {
	fast_io();
