template < class Value >
auto rotate180(std::vector< std::vector< Value > > const& a) {
  std::size_t h = a.size(), w = a.front().size();
  std::vector< std::vector< Value > > b(h, std::vector< Value >(w));
  for (std::size_t i = 0; i < h; i++) {
    for (std::size_t j = 0; j < w; j++) {
      b.at(h-1-i).at(w-1-j) = a.at(i).at(j);
    }
  }
  return b;
}

