  int A, B; std::cin >> A >> B;
  std::swap(A,B);
  A--,B--;
  int n = 100;
  int l = n / 2;
  auto grid = make_vector<2,int>(n,n);
  rep(i,l,n) rep(j,0,n) {
    at(grid,i,j) = 1;
  }

  loop(2) {
    for (int i = 1; i < n; i += 2) {
      if (A==0) break;
      for (int j = 1; j < n; j += 2) {
        if (A==0) break;
        at(grid,i,j) = 1;
        A--;
      }
    }

    assert(A==0);
    std::swap(A,B);
    grid = rotate180(grid);
    for (auto&& v : grid) {
      for (int & x : v)  {
        x ^= 1;
      }
    }
  }

  std::cout << n << " " << n << std::endl;
  for (auto&& v : grid) {
    rep(i,0,n) {
      std::cout << (v.at(i) ? '#' : '.');
    }
    std::cout << std::endl;
  }
  return 0;
}

