				num[i][j] = '#';
				cnt_B++;
			}
		}
	}
	else {
		int cnt_A = 0, cnt_B = 0;
		for(int i = 1; i <= maxn; i++)
			for(int j = 1; j <= maxn; j++)
				num[i][j] = '#';
		if(cnt_B < B - 1) {
			for(int i = 2; i <= maxn; i += 2) {
				num[1][i] = num[2][i - 1] = '.';
				cnt_B++;
				cnt_A++;
				if(cnt_B == B - 1) {
					for(int j = 2; j <= i; j += 2)num[2][j] = '.';
					cnt_A -= (i / 2);
					cnt_A++;
					break;
				}
			}
		}
		if(cnt_B < B - 1) {
			int l;
			for(int i = 3; i <= maxn; i++) {
				if(cnt_B == B - 1)break;
				if(i & 1)l = 2;
				else l = 1;
				for(int j = l; j <= maxn; j += 2) {
					num[i][j] = '.';
					cnt_B++;
					cnt_A++;
					if(cnt_B == B - 1) {
						if(l == 1)l = 2;
						else if(l == 2)l = 1;
						for(int k = l; k <= j; k += 2)num[i][k] = '.';
						for(int k = j + 1; j <= 100; k++)num[i - 1][k] = '.';
						cnt_A -= 49;
						break;
					}
				}
			}
		}
		for(int i = maxn; i >= 1; i -= 2) {
			if(cnt_A == A)break;
			for(int j = 1; j <= maxn; j += 2) {
				if(cnt_A == A)break;
				num[i][j] = '.';
				cnt_A++;
			}
		}
	}
	printf("100 100\n");
	for(int i = 1; i <= maxn; i++) {
		for(int j = 1; j <= maxn; j++)
			printf("%c", num[i][j]);
		printf("\n");
	}
	return 0;
}

