#include<bits/stdc++.h>
using namespace std;

int main() {
  // input
  int A, B;  cin >> A >> B;

  // grid
  int h, ha, hb;
  int w = max((A * 2) - 1, (B * 2) - 1);
  ha = (A - 1) / ((w + 1) / 2) + 1;
  hb = (B - 1) / ((w + 1) / 2) + 1;
  h = ha + hb;
  vector<char> grid(h * w, '.');
  for (int i = 0; i < ha * w; i++) {
    grid.at(i) = '#';
  }

  // paint
  for (int i = 0; i < (A - 1) * 2; i += 2) {
    grid.at(i) = '.';
  }
  for (int i = h * w - 1; i > h * w - (B - 1) * 2 - 1; i -= 2) {
    grid.at(i) = '#';
  }

  // output
  cout << h * 2 << " " << w << endl;
  for (int i = 0; i < h * w; i++) {
    if (i != 0 && i <= ha * w && i % w == 0) {
      for (int j = 0; j < w; j++) cout << "#";
      cout << endl;
    }
    if (i >= ha * w && i % w == 0) {
      for (int j = 0; j < w; j++) cout << ".";
      cout << endl;
    }
    cout << grid.at(i);
    if ((i + 1) % w == 0) {
      cout << endl;
    }
  }

  return 0;
}

