                            for (int k2 = j; k2 <= j + 2; k2++) {
                                k[k1][k2] = '#';
                            }
                        }
                        k[i + 1][j + 1] = '.';
                        b--;
                        a--;
                    }
                }
                for (int i = koni; i < 99; i += 2) {
                    if (b <= 0) break;
                    for (int j = 0; j < 99; j += 2) {
                        if (b <= 0) break;
                        k[i][j] = '#';
                        b--;
                    }
                }
