                    for (int j = 0; j < 99; j += 4) {
                        if (b <= 0 || a <= 0) break;
                        for (int k1 = i; k1 <= i + 2; k1++) {
                            for (int k2 = j; k2 <= j + 2; k2++) {
                                k[k1][k2] = '.';
                            }
                        }
                        k[i + 1][j + 1] = '#';
                        b--;
                        a--;
                    }
                }
                for (int i = koni; i < 99; i += 2) {
                    if (a <= 0) break;
                    for (int j = 0; j < 99; j += 2) {
                        if (a <= 0) break;
                        k[i][j] = '.';
                        a--;
                    }
                }
