    sb.append(String.format("%d %d\n", 40, 100));

    for (int i = 0; i < 10; i++) {
      for (int j = 0; j < 50; j++) {
        if (b > 1) {
          sb.append(".#");
          b--;
        } else {
          sb.append("..");
        }
      }
      sb.append("\n");
      for (int j = 0; j < 50; j++) {
        sb.append(".");
      }
      sb.append("\n");
    }

    for (int i = 0; i < 10; i++) {
      for (int j = 0; j < 50; j++) {
        sb.append("#");
      }
      sb.append("\n");
      for (int j = 0; j < 50; j++) {
        if (a > 1) {
          sb.append(".#");
          a--;
        } else {
          sb.append("##");
        }
      }
      sb.append("\n");
    }
    return sb.toString();
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int a = reader.nextInt();
    int b = reader.nextInt();
    out.print(solve(a, b));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

