            for (int j = 0; j * 2 < s; ++j) {
                boolean t = (i & 1) == 1 || (j & 1) == 1;
                map[i][j] = t;
                map[s - i - 1][s - j - 1] = !t;
            }
        }
        a = (s / 4 * s / 2) + 1 - a;
        b = (s / 4 * s / 2) + 1 - b;
        for (int i = 0; i < s; ++i) {
            for (int j = 0; j * 2 < s; ++j) {
                if (a > 0 && !map[i][j]) {
                    a--;
                    map[i][j] = true;
                }
                if (b > 0 && map[s - i - 1][s - j - 1]) {
                    b--;
                    map[s - i - 1][s - j - 1] = false;
                }
            }
        }
        out.println(s + " " + s);
        for (int i = 0; i < s; ++i) {
            for (int j = 0; j < s; ++j) {
                out.print(map[i][j] ? "#" : ".");
            }
            out.println();
        }
    }

