import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.IOException;
import java.util.NoSuchElementException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FasterScanner in = new FasterScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, FasterScanner in, PrintWriter out) {
            int a = in.nextInt();
            int b = in.nextInt();

            boolean[][] field = new boolean[100][100];
            for (int i = 0; i < 50; i++) for (int j = 0; j < 100; j++) field[i][j] = false;
            for (int i = 50; i < 100; i++) for (int j = 0; j < 100; j++) field[i][j] = true;

            a--;
            b--;

            for (int i = 0; i < a; i++) {
                int x = (i * 2) % 100;
                int y = 2 * ((i * 2) / 100);
                field[y][x] = true;
            }
            for (int i = 0; i < b; i++) {
                int x = (i * 2) % 100;
                int y = 2 * ((i * 2) / 100);
                field[99 - y][99 - x] = false;
            }

            out.println(100 + " " + 100);
            for (int i = 0; i < 100; i++) {
                for (int j = 0; j < 100; j++) out.print(field[i][j] ? '.' : '#');
                if (i != 99) out.println();
            }
        }

    }

    static class FasterScanner {
        private InputStream in;
        private byte[] buffer;
        private int bufPointer;
        private int bufLength;

        public FasterScanner(InputStream in) {
            this.in = in;
            buffer = new byte[1024];
        }

        private boolean hasNextByte() {
            if (bufPointer < bufLength) return true;
            bufPointer = 0;
            try {
                bufLength = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return (bufLength > 0);
        }

        private int readByte() {
            if (hasNextByte()) return buffer[bufPointer++];
            return -1;
        }

        private static boolean isPrintableChar(int c) {
            return (c >= 33 && c <= 126);
        }

        public boolean hasNext() {
            while (hasNextByte() && !isPrintableChar(buffer[bufPointer])) bufPointer++;
            return hasNextByte();
        }

        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }

        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || b > '9') throw new NumberFormatException();

            while (true) {
                if (b >= '0' && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }

    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskD solver = new TaskD();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskD {
		final int n = 100;

		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int a = in.nextInt();
			int b = in.nextInt();
			char[][] s;
			if (a <= b) {
				s = solve(a, b);
			} else {
				s = invert(solve(b, a));
			}

			out.println(n + " " + n);
			for (int i = 0; i < n; i++) {
				out.println(new String(s[i]));
			}
		}

		private char[][] invert(char[][] s) {
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					s[i][j] = (char) (s[i][j] ^ '.' ^ '#');
				}
			}
			return s;
		}

		private char[][] solve(int a, int b) {
			char[][] s = new char[n][n];
			for (char[] arr : s) {
				Arrays.fill(arr, '.');
			}
			--a;

			for (int r = 0; r + 2 < n; r += 4) {
				for (int c = 0; c + 2 < n; c += 4) {
					if (a == 0 || b == 0) {
						break;
					}
					--a;
					--b;
					for (int i = 0; i < 3; i++) {
						for (int j = 0; j < 3; j++) {
							s[r + i][c + j] = '#';
						}
					}
					s[r + 1][c + 1] = '.';
				}
			}

			outer:
			while (b > 0) {
				for (int r = 0; r + 2 < n; r += 4) {
					for (int c = 0; c + 2 < n; c += 4) {
						boolean ok = true;
						for (int i = 0; i < 3; i++) {
							for (int j = 0; j < 3; j++) {
								if (s[r + i][c + j] == '#') {
									ok = false;
								}
							}
						}
						if (ok) {
							s[r + 1][c + 1] = '#';
							--b;
							continue outer;
						}
					}
				}
			}

			return s;
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

