        Map<Integer, Integer> memo = new HashMap<Integer, Integer>();
        for (int item : a) {
            memo.put(item, memo.getOrDefault(item, 0) + 1);
            memo.put(item - 1, memo.getOrDefault(item - 1, 0) + 1);
            memo.put(item + 1, memo.getOrDefault(item + 1, 0) + 1);
