                Arrays.fill(res[i], '.');
        }
        /*
        a-1,b-1分を相互につぶす
         */
        int cnt = 0;
        for (int i = 0; i < k; i += 2) {
            for (int j = 0; j < 2 * k; j += 2) {
                if (cnt == (b - 1))
                    break;
                res[i][j] = '.';
                cnt++;
            }
        }
        cnt = 0;
        for (int i = k + 1; i < 2 * k; i += 2) {
            for (int j = 0; j < 2 * k; j += 2) {
                if (cnt == (a - 1))
                    break;
                res[i][j] = '#';
                cnt++;
            }
        }
        for (char[] item : res) {
            StringBuilder builder = new StringBuilder();
            for (char c : item) {
                builder.append(c);
            }
            out.println(builder.toString());
        }
    }

