	static class TaskD {
		public void solve(int testNumber, Scanner sc, PrintWriter out) {

			int a = sc.nextInt();
			int b = sc.nextInt();

			int w = 99, h = 100;
			boolean[][] block = new boolean[h][w];
			for (int i = h / 2; i < h; i++) {
