        boolean trueiswhite = true;
        if(a<b){
            int tmp = a;
            a=b;
            b=tmp;
            trueiswhite=false;
        }

        if(b<16){
            for(int i=0;i<b;++i){
                for(int j=i*6;j<i*6+3;++j){
                    for(int k=0;k<96;++k)map[j][k]=false;
                }
            }
            for(int i=(b-1)*6;i<96;++i)for(int k=0;k<96;++k)map[i][k]=false;
            a-=(b-1);
            for(int i=1;i<96;i+=6){
                for(int j=1;j<96;j+=2){
                    map[i][j]=true;
                    --a;
                    if(a==0){
