            a-=16;
            for(int i=1;i<96;i+=6){
                for(int j=1;j<96;j+=2){
                    map[i][j]=true;
                    --a;
                    if(a==0)break;
                }
                if(a==0)break;
            }

            for(int i=4;i<96;i+=6){
                for(int j=1;j<96;j+=2){
                    map[i][j]=false;
                    --b;
                    if(b==0){
                        solve(map, trueiswhite);
                        return;
                    }
                }
            }

        }


