            int root = get_root_uf(parent.get(index));
            parent.put(index,root);
            return root;
        }
        boolean is_same_uf(int x, int y){
            if(get_root_uf(x) == get_root_uf(y)) return true;
            else return false;
        }
        void unite_uf(int receiver, int attacker){
            parent.put(get_root_uf(attacker), get_root_uf(receiver));
        }

        void add(int e){
