                    ans[0][i] = '#';
                    ans[1][i] = '#';
                } else {
                    ans[0][i] = '.';
                    ans[1][i] = '.';
                }
            }
            for (int i = 0; i < a - b; i++) {
                ans[1][2 * i + 1] = '#';
            }
        }
        out.println(2 + " " + n);
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < n; j++) {
                out.print(ans[i][j]);
            }
            out.println();
        }

    }

