        	}else if(count%2 == 0){
        		for(int i=0; i<63; i++){
        			System.out.print(few);
        		}
        		System.out.println("");
        		printrow(n, many, few, count-1);
        	}else if(n >= 32){
        		for(int i=0; i<31; i++){
        			System.out.print(many + few);
        		}
        		System.out.println(many);
        		printrow(n-32, many, few, count-1);
        	}else if(n==0){
        		for(int i=0; i<63; i++){
        			System.out.print(few);
        		}
