	internal class Program {
		private static void Main(string[] args) {
			var sw = new StreamWriter(OpenStandardOutput()) { AutoFlush = false };
			SetOut(sw);
			new Calc().Solve();
			Out.Flush();
		}

		public class Calc
		{
			public void Solve() {
				int A = NextInt(), B = NextInt();
				var b = '#';
				var w = '.';

				Action<int, int> make = (x, y) =>
				{
					$"{y} {x}".WL();

					var first = A < B ? b : w;

					for (int i = 0; i < y; i++) {
						var n = i % 2 == 0 ? first : first == w ? b : w;
						for (int j = 0; j < x; j++) {
							n.W();
							n = n == b ? w : b;
						}

						"".WL();
					}

				};

				for (int i = 1; i <= 100; i++) {
					for (int j = 1; j <= 100; j++) {
						var s = i * j;
						var l = s / 2;
						var r = s - l;
						if ((A != l || B != r) && (A != r || B != l)) continue;

						make(j, i);

						return;
					}
				}

				var ans=new StringBuilder();

				var str = "";
				var next = b;
				var wcount = 1;

				var f = A > B;
				if (f) Utils.Utils.Swap(ref A, ref B);
				var W = B * 2;

				for (int i = 0; i < B*2; i++) {
					str += next;
					next = next == b ? w : b;
				}

				//str.WL();

				var bline = Enumerable.Repeat(b, W).StringJoin();
				var wline = Enumerable.Repeat(w, W).StringJoin();
				ans.AppendLine(str);
				ans.AppendLine(wline);


				var H = 1;
				while (wcount<A) {
					W -= 2;
					H += 2;

					ans.AppendLine(bline);
					ans.AppendLine(wline);
					wcount++;
				}

				var splited=ans.ToString().Split('\n');
				if (f) splited = splited.Select(x => x.Select(k => k == w ? b : w).StringJoin()).ToArray();
				$"{H+1} {W}".WL();
				splited.Where(x=>x.Length>0).Select(x => x.Substring(0, W)).WL();

				return;
			}
		}

	}
