public class Program
{
    public static void Solve()
    {
        var white = I;
        var black = I;
        var grid = new Grid2D<char>(100, 100);
        foreach (var p in Point2D.InnerPoints(grid.Size))
            grid[p] = '.';

        var row = true;
        var h = 3;
        var w = 3;
        var whiteCnt = 1;

        while (whiteCnt < white)
        {
            if (row)
            {
                var j = grid.Width - 1;
                while (whiteCnt < white && j >= 0)
                {
                    while (j >= 0 && grid[h, j] == '.')
                    {
                        grid[h, j] = '#';
                        j--;
                    }
                    j--;
                    whiteCnt++;
                }
                h += 3;
            }
            else
            {
                var i = grid.Height - 1;
                while (whiteCnt < white && i >= 0)
                {
                    while (i >= 0 && grid[i, w] == '.')
                    {
                        grid[i, w] = '#';
                        i--;
                    }
                    i--;
                    whiteCnt++;
                }
                w += 3;
            }
            row = !row;
        }

        h = 3;
        w--;
        var initW = w;
        var blackCnt = white == 1 ? 0 : 1;

        while (blackCnt < black)
        {
            if (w >= grid.Width)
            {
                h += 3;
                w = initW;
                continue;
            }

            if (black - blackCnt == 1)
            {
                foreach (var j in Range(w, grid.Width))
                {
                    grid[h - 1, j] = '#';
                    grid[h, j] = '.';
                }
                blackCnt++;
                break;
            }

            if (grid[h, w] == '#')
            {
                grid[h - 1, w] = '#';
                grid[h, w] = '.';
            }
            else
            {
                grid[h - 1, w] = grid[h, w + 1] = '#';
            }
            blackCnt += 2;
            w += 2;
        }

        Console.WriteLine($"{grid.Height} {grid.Width}");

        foreach (var i in Range(grid.Height))
        {
            foreach (var j in Range(grid.Width))
                Console.Write(grid[i, j]);
            Console.WriteLine();
        }
    }

