	internal class Program {
		private static void Main(string[] args) {
			var sw = new StreamWriter(OpenStandardOutput()) { AutoFlush = false };
			SetOut(sw);
			new Calc().Solve();
			Out.Flush();
		}

		public class Calc
		{
			public void Solve() {
				int A = NextInt(), B = NextInt();
				var b = '#';
				var w = '.';

				Action<int, int> make = (x, y) =>
				{

					var first = A < B ? b : w;

					for (int i = 0; i < y; i++) {
						var n = i % 2 == 0 ? first : first == w ? b : w;
						for (int j = 0; j < x; j++) {
							n.W();
							n = n == b ? w : b;
						}

						"".WL();
					}

				};

				for (int i = 1; i <= 100; i++) {
					for (int j = 1; j <= 100; j++) {
						var s = i * j;
						var l = s / 2;
						var r = s - l;
						if ((A != l || B != r) && (A != r || B != l)) continue;

						make(j, i);

						return;
					}
				}

				var ans=new StringBuilder();

				var str = "";
				var next = b;
				var W = B * 2;
				var wcount = 1;

				var f = A > B;
				if (f) Utils.Utils.Swap(ref A, ref B);

				for (int i = 0; i < B*2; i++) {
					str += next;
					next = next == b ? w : b;
				}

				str.WL();

				var bline = Enumerable.Repeat(b, W).StringJoin();
				var wline = Enumerable.Repeat(w, W).StringJoin();
				ans.AppendLine(str);
				ans.AppendLine(wline);


				var H = 1;
				while (wcount<A) {
					W -= 2;
					H += 2;

					ans.AppendLine(bline);
					ans.AppendLine(wline);
					wcount++;
				}

				var splited=ans.ToString().Split('\n');
				if (f) splited = splited.Select(x => x.Select(k => k == w ? b : w).StringJoin()).ToArray();
				splited.Where(x=>x.Length>0).Select(x => x.Substring(0, W)).WL();

				return;
			}
		}

	}
}
namespace Nakov.IO {
	using System;
	using System.Text;
	using System.Globalization;

	public static class Cin {
		public static string NextToken() {
			StringBuilder tokenChars = new StringBuilder();
			bool tokenFinished = false;
			bool skipWhiteSpaceMode = true;
			while (!tokenFinished) {
				int nextChar = Console.Read();
				if (nextChar == -1) {
					tokenFinished = true;
				} else {
					char ch = (char)nextChar;
					if (char.IsWhiteSpace(ch)) {
						if (!skipWhiteSpaceMode) {
							tokenFinished = true;
							if (ch == '\r' && (Environment.NewLine == "\r\n")) {
								Console.Read();
							}
						}
					} else {
						skipWhiteSpaceMode = false;
						tokenChars.Append(ch);
					}
				}
			}

			string token = tokenChars.ToString();
			return token;
		}

		public static int NextInt() {
			string token = Cin.NextToken();
			return int.Parse(token);
		}
		public static long NextLong() {
			string token = Cin.NextToken();
			return long.Parse(token);
		}
		public static double NextDouble(bool acceptAnyDecimalSeparator = true) {
			string token = Cin.NextToken();
			if (acceptAnyDecimalSeparator) {
				token = token.Replace(',', '.');
				double result = double.Parse(token, CultureInfo.InvariantCulture);
				return result;
			} else {
				double result = double.Parse(token);
				return result;
			}
		}
		public static decimal NextDecimal(bool acceptAnyDecimalSeparator = true) {
			string token = Cin.NextToken();
			if (acceptAnyDecimalSeparator) {
				token = token.Replace(',', '.');
				decimal result = decimal.Parse(token, CultureInfo.InvariantCulture);
				return result;
			} else {
				decimal result = decimal.Parse(token);
				return result;
			}
		}

	}
}

namespace CS_Contest.Loop {
	[DebuggerStepThrough]
	public static class Loop {
		public static void REP(this int n, Action<int> act) {
			for (var i = 0; i < n; i++) {
				act(i);
			}
		}

		public static void ForeachWith<T>(this IEnumerable<T> ie, Action<int, T> act) {
			var i = 0;
			foreach (var item in ie) {
				act(i, item);
				i++;
			}
		}

		public static void Foreach<T>(this IEnumerable<T> ie, Action<T> act) {
			foreach (var item in ie) {
				act(item);
			}
		}


	}

	public class Generate
	{
		public static IEnumerable<int> Seq(int s, int e) => Seq(s, e, 1);
		public static IEnumerable<int> Seq(int s, int e, int a) {
			while (s != e) {
				yield return s;
				s += a;
			}
		}
		public static List<T> Repeat<T>(Func<int, T> result, int range) =>
			Enumerable.Range(0, range).Select(result).ToList();
	}
}

