		{
			var cin = new Scanner2();
			int a = cin.Int();
			int b = cin.Int();

			int l;
			int m;
			char lc;
			char mc;
			if (a > b) {
				l = b;
				m = a;
				lc = '#';
				mc = '.';
			} else {
				l = a;
				m = b;
				lc = '.';
				mc = '#';
			}

			int v = 0;
			int h = 100;
			var sb = new StringBuilder();
			int remainL = l - 1;
			int remainM = m;
			int count = (remainL + 50 - 1) / 50;
			int tempMCount = 0;
			for (int i = 0; i < count; i++) {
				++v;
				tempMCount = 0;
				for (int j = 0; j < 100; j++) {
					if (remainL == 0) {
						sb.Append(lc);
					} else {
						if (i % 2 == 0) {
							if (j % 2 == 0) {
								sb.Append(lc);
								--remainL;
							} else {
								sb.Append(mc);
								--remainM;
								tempMCount++;
							}
						} else {
							if (j % 2 == 0) {
								sb.Append(mc);
								--remainM;
								tempMCount++;
							} else {
								sb.Append(lc);
								--remainL;
							}
						}
					}
				}

				sb.AppendLine();
			}

			if (count > 0) {
				++v;
				for (int j = 0; j < 100; j++) {
					sb.Append(mc);
				}

				sb.AppendLine();
				remainM += (tempMCount - 1);
			}

			while (remainM > 0) {
				++v;
				for (int j = 0; j < 100; j++) {
					sb.Append(lc);
				}

				sb.AppendLine();

				++v;
				for (int j = 0; j < 100; j++) {
					if (remainM == 0) {
						sb.Append(lc);
					} else {
						if (j % 2 == 0) {
							sb.Append(lc);
						} else {
							sb.Append(mc);
							remainM--;
						}
					}
				}

				sb.AppendLine();
			}

			Console.WriteLine($"{v} {h}");
			Console.WriteLine(sb);
		}
	}

