class Solve{
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int H = 100;
        int W = 100;
        int B = re.i();
        int A = re.i();
        bool[,] Map = new bool[H,W];
        for(int i=H/2;i<H;i++){
            for(int j=0;j<W;j++){
                Map[i,j] = true;
            }
        }
        A--;
        B--;
        for(int i=0;i<H/2;i+=2){
            for(int j=0;j<W;j+=2){
                if(A > 0){
                    A--;
                    Map[i,j] = !Map[i,j];
                }
            }
        }
        for(int i=H/2+1;i<H;i+=2){
            for(int j=0;j<W;j+=2){
                if(B > 0){
                    B--;
                    Map[i,j] = !Map[i,j];
                }
            }
        }
        sb.Append(H+" "+W+"\n");
        for(int i=0;i<H;i++){
            for(int j=0;j<W;j++){
                if(Map[i,j]){
                    sb.Append('#');
                }
                else{
                    sb.Append('.');
                }
            }
            sb.Append("\n");
        }
    }
}
