struct Solve {
  int [N][N] c;
  bool [N][N] v;
  int [2] n;
  int X, Y;
  void f (int x, int y, int color) {
    if (v[x][y] || color != c[x][y]) {
      return;
    }
    v[x][y] = true;
    if (x > 0) {
      f (x - 1, y, color);
    }
    if (x + 1 < X) {
      f (x + 1, y, color);
    }
    if (y > 0) {
      f (x, y - 1, color);
    }
    if (y + 1 < Y) {
      f (x, y +1, color);
    }
  }
  void g () {
    foreach (i; 0 .. X) {
      foreach (j; 0 .. Y) {
        v[i][j] = false;
      }
    }
    n[] = 0;
    foreach (i; 0 .. X) {
      foreach (j; 0 .. Y) {
        if (!v[i][j]) {
          n[c[i][j]]++;
          f (i, j, c[i][j]);
        }
      }
    }
  }
  void rnd () {
    int n = a + b;
    X = N;
    Y = N;
    X = uniform (5, N, gen);
    Y = uniform (5, N, gen);
    if (X > n) X = n;
    if (Y > n) Y = n;
    /*
    foreach (t; 0 .. b) {
      int x = uniform (0, N);
      int y = uniform (0, N);
      c[x][y] = 1;
    }
    */
    int B = b;
