        foreach (j; 0 .. Y) {
          c[i][j] = 0;
        }
      } 
      foreach (z; 0 .. b) {
        int x = z % X;
        int y = (2 * z) % Y;
        c[x][y] = 1;
      }
    } else {
      foreach (i; 0 .. X) {
        foreach (j; 0 .. Y) {
          c[i][j] = uniform (0, 2, gen);
        }
      }
    }
  }
  void print () {
    writeln (X, ' ', Y);
    foreach (i; 0 .. X) {
      foreach (j; 0 .. Y) {
        write (c[i][j] == x ? "." : "#");
      }
      writeln ();
    }
  }
  int fit () {
    g ();
    return  (a - n[0]) * (a - n[0]) + (b - n[1]) * (b - n[1]);
  }
}

