auto solve( long a, long b )
{
	auto ansss = new char[][]( 40, 100 );
	a--;
	b--;

	// 黒地に白点を打つ
	for( auto y = 0L; y < ansss.length / 2; y += 2 )
	{
		ansss[ y     ][] = '#';
		ansss[ y + 1 ][] = '#';
		for( auto x = 0L; x < ansss[ y ].length && 0 < a; x += 2 )
		{
			ansss[ y ][ x ] = '.';
			a--;
		}
	}

	// 白地に黒点を打つ
	for( auto y = ansss.length.signed / 2 + 1; y < ansss.length; y += 2 )
	{
		ansss[ y - 1 ][] = '.';
		ansss[ y     ][] = '.';
		for( auto x = 0L; x < ansss[ y ].length && 0 < b; x += 2 )
		{
			ansss[ y ][ x ] = '#';
			b--;
		}
	}
	return format( "%s %s\n%s", ansss.length, ansss[ 0 ].length, ansss.join( '\n' ) );
}

