struct Solve {
  int [N][N] c;
  bool [N][N] v;
  int [2] n;
  int X, Y;
  void f (int x, int y, int color) {
    if (v[x][y] || color != c[x][y]) {
      return;
    }
    v[x][y] = true;
    if (x > 0) {
      f (x - 1, y, color);
    }
    if (x + 1 < X) {
      f (x + 1, y, color);
    }
    if (y > 0) {
      f (x, y - 1, color);
    }
    if (y + 1 < Y) {
      f (x, y +1, color);
    }
  }
  void g () {
    foreach (i; 0 .. X) {
      foreach (j; 0 .. Y) {
        v[i][j] = false;
      }
    }
    n[] = 0;
    foreach (i; 0 .. X) {
      foreach (j; 0 .. Y) {
        if (!v[i][j]) {
          n[c[i][j]]++;
          f (i, j, c[i][j]);
        }
      }
    }
  }
  void rnd () {
    int n = a + b;
    X = N;
    Y = N;
    X = uniform (5, N, gen);
    Y = uniform (5, N, gen);
    if (X > n) X = n;
    if (Y > n) Y = n;
    /*
    foreach (t; 0 .. b) {
      int x = uniform (0, N);
      int y = uniform (0, N);
      c[x][y] = 1;
    }
    */
    int B = b;
    if (a < 5) {
      foreach (i; 0 .. X) {
        foreach (j; 0 .. Y) {
          c[i][j] = 0;
        }
      } 
      foreach (z; 0 .. b) {
        int x = z % X;
        int y = (2 * z) % Y;
        c[x][y] = 1;
      }
    } else {
      foreach (i; 0 .. X) {
        foreach (j; 0 .. Y) {
          c[i][j] = uniform (0, 2, gen);
        }
      }
    }
  }
  void print () {
    writeln (X, ' ', Y);
    foreach (i; 0 .. X) {
      foreach (j; 0 .. Y) {
        write (c[i][j] == x ? "." : "#");
      }
      writeln ();
    }
  }
  int fit () {
    g ();
    return  (a - n[0]) * (a - n[0]) + (b - n[1]) * (b - n[1]);
  }
}

bool test (ref Solve s) {
  s.rnd ();
  int cur = s.fit ();
  int f = 0;
  while (cur > 0) {
    int x = uniform (0, s.X, gen);
    int y = uniform (0, s.Y, gen);
    int OX = s.X;
    int OY = s.Y;
    s.X = uniform (max (2, s.X - 1), min (N, s.X + 1) + 1, gen);
    s.Y = uniform (max (2, s.Y - 1), min (N, s.Y + 1) + 1, gen);
    int next = s.fit ();
    if (next < cur) {
      cur = next;
      f = 0;
      debug {stderr.writeln (cur); }
    } else {
      s.c[x][y] ^= 1;
      s.X = OX;
      s.Y = OY;
      if (++f >= 1000) { return false; }
    }
  }
  return true;
}

