proc draw(board: var seq[seq[char]], rest_tmp, start: int, color: char): seq[seq[char]] =
  let K = 50
  var rest = rest_tmp
  for i in countup(start, 2 * K, 2):
    for j in countup(0, 2 * K, 2):
