import math


def main():
    A, B = map(int, input().split())

    if A == B == 1:
        print(1, 2)
        print('.#')

    N = 50 if max(A, B) >= 50 else max(A, B)

    print(N, (math.ceil((A - 1) / 50) + math.ceil((B - 1) / 50)) * 2)
    if A != 1:
        a = A
        while a > 0:
            for i in range(N):
                if a <= 0:
                    print('..', end='')
                else:
                    print('#.', end='')
                    a -= 1
            print()
            print('.' * N * 2)
    if B != 1:
        b = B
        while b > 0:
            for i in range(N):
                if b <= 0:
                    print('##', end='')
                else:
                    print('##', end='')
                    b -= 1
            print()
            print('#' * N * 2)


