def solve():
    hb = min(B, 12)
    h = hb * 2 * 3
    w = 100
    # If not flipped, False -> White (A), True -> Black (B)
    grid = [[None] * w for _ in range(h)]
    for i in range(hb):
        for c in range(w):
            for j in range(3):
                grid[6 * i + j][c] = False
                grid[6 * i + 3 + j][c] = True
    white = hb
    black = hb

    def paint_black(i):
        nonlocal black
        if black == B:
            return
        for c in range(0, w, 2):
            grid[6 * i + 1][c] = True
            black += 1
            if black == B:
                return

    def paint_white(i):
        nonlocal white
        if white == A:
            return
        for c in range(0, w, 2):
            grid[6 * i + 4][c] = False
            white += 1
            if white == A:
                return

    for i in range(hb):
        paint_black(i)
        paint_white(i)
    return grid


