import sys

sys.setrecursionlimit(10 ** 8)
read = sys.stdin.buffer.read
readline = sys.stdin.buffer.readline
readlines = sys.stdin.buffer.readlines

A, B = map(int, readline().split())


def solve():
    W = 100
    hw = B // 50 + 2
    hb = A // 50 + 2
    H = hw + hb
    grid = [[i >= hw] * W for i in range(H)]  # true => black

    def paint_black():
        black = 1
        for r in range(hw - 1):
            for c in range(0, W, 2):
                if black == B:
                    return
                grid[r][c] = True
                black += 1

    def paint_white():
        white = 1
        for r in range(hw + 1, H):
            for c in range(0, W, 2):
                if white == A:
                    return
                grid[r][c] = False
                white += 1

    paint_black()
    paint_white()
    return grid


def print_grid(grid):
    h, w = len(grid), len(grid[0])
    print(h, w)
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                print("#", end="")
            else:
                print(".", end="")
        print()


