    if B != 1:
        if A != 1:
            b = B - 1
        else:
            b = B
        ans.append('#' * N * 2)
        while b > 0:
            tmp = []
            for i in range(N):
                if b <= 0:
                    tmp.append('##')
                else:
                    tmp.append('.#')
                    b -= 1
            ans.append('#' * N * 2)
    print(len(ans), len(ans[0]))
    for l in ans:
