def solve():
    A, B = get_next_ints()
    K = 2
    while K * 2 * K / 4 < max(A, B):
        K *= 2
    grid = [["#"] * 2 * K for i in range(K)]
    grid.extend([["."] * 2 * K for i in range(K)])
    # print(grid)

    x, y = 0, 0
    while A > 1:
        grid[y][x] = "."
        if x + 2 >= 2 * K:
            y += 2
            x = 0
        else:
            x += 2
        A -= 1
