    while B > 1:
        grid[y][x] = "#"
        if x - 2 < 0:
            y -= 2
            x = 2 * K - 1
        else:
            x -= 2
        B -= 1
    print(2 * K, 2 * K)
    for row in grid:
        print(''.join(row))
