    stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let a: usize = itr.next().unwrap().parse().unwrap();
    let b: usize = itr.next().unwrap().parse().unwrap();
    let h = 100;
    let w = 100;

    let mut g: Vec<char> = vec!['.'; h * w];
    for i in 0..50 {
        for j in 0..100 {
            g[i * w + j] = '#';
        }
    }

    let mut y = 1;
    let mut x = 1;
    let mut cnt = 1;
    while cnt < a {
        g[y * w + x] = '.';
        x += 2;
        if x >= 100 {
            x = 1;
            y += 2;
        }
        cnt += 1;
    }
    y = 51;
    x = 1;
    cnt = 1;
    while cnt < b {
        g[y * w + x] = '#';
        x += 2;
        if x >= 100 {
            x = 1;
            y += 2;
        }
        cnt += 1;
    }

    let mut out = Vec::new();
    writeln!(out, "{} {}", h, w).ok();
    for i in 0..h {
        for j in 0..w {
            write!(out, "{}", g[i * w + j]).ok();
        }
        writeln!(out, "").ok();
    }
    stdout().write_all(&out).unwrap();
}

