use std::io::{BufRead, Write};
use std::io;

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut buf = String::new();
    input.read_line(&mut buf).unwrap();
    let (a, b): (usize, usize) = {
        let mut split = buf.split_whitespace();
        (split.next().unwrap().parse().unwrap(), split.next().unwrap().parse().unwrap())
    };
    let mut upper_grid = vec![vec![false; 100]; 100];
    let mut lower_grid = vec![vec![true; 100]; 100];
    let mut count_a = 0;
    for x in 0..24 {
        for y in 0..24 {
            if count_a + 1 == a { break; }
            count_a += 1;
            upper_grid[y * 2 + 1][x * 2 + 1] ^= true;
        }
    }
    let mut count_b = 0;
    for x in 0..24 {
        for y in 0..24 {
            if count_b + 1 == b { break; }
            count_b += 1;
            lower_grid[y * 2 + 1][x * 2 + 1] ^= true;
        }
    }
    writeln!(output, "100 100").unwrap();
    for row in upper_grid.into_iter().chain(lower_grid) {
        for column in row {
            write!(output, "{}", if column { '.' } else { '#' }).unwrap();
        }
        writeln!(output, "").unwrap();
    }
}

