fn solve() {
    let (mut a, mut b) = get!(usize, usize);

    let mut ans = vec![vec![false; 100]; 100];

    let mut i = 0;
    let mut j = 0;
    while a > 1 {
        ans[i][j] = true;
        // debug!(i, j);
        j += 2;
        if j >= 100 {
            j = 0;
            i += 2;
        }
        a -= 1;
    }

    for w in i + 2..100 {
        for k in 0..100 {
            ans[w][k] = true;
        }
    }
    j = 0;
    i += 3;
    while b > 1 {
        ans[i][j] = false;
        j += 2;
        if j >= 100 {
            j = 0;
            i += 2;
        }
        b -= 1;
    }

    util::with_bufwriter(|mut out| {
        writeln!(out, "100 100").unwrap();
        for v in ans {
            writeln!(
                out,
                "{}",
                v.iter()
                    .map(|&x| if x { '.' } else { 'x' })
                    .collect::<String>()
            ).unwrap();
        }
    });
}

use std::io::{BufRead, Write};
use std::io;

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut buf = String::new();
    input.read_line(&mut buf).unwrap();
    let (a, b): (usize, usize) = {
        let mut split = buf.split_whitespace();
        (split.next().unwrap().parse().unwrap(), split.next().unwrap().parse().unwrap())
    };
    let mut upper_grid = vec![vec![false; 100]; 50];
    let mut lower_grid = vec![vec![true; 100]; 50];
    let mut count_a = 0;
    for x in 0..24 {
        for y in 0..24 {
            if count_a + 1 == a { break; }
            count_a += 1;
            upper_grid[y * 2 + 1][x * 2 + 1] ^= true;
        }
    }
    let mut count_b = 0;
    for x in 0..24 {
        for y in 0..24 {
            if count_b + 1 == b { break; }
            count_b += 1;
            lower_grid[y * 2 + 1][x * 2 + 1] ^= true;
        }
    }
    writeln!(output, "100 100").unwrap();
    for row in upper_grid.into_iter().chain(lower_grid) {
        for column in row {
            write!(output, "{}", if column { '.' } else { '#' }).unwrap();
        }
        writeln!(output, "").unwrap();
    }
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
