fn solve() {
    let (mut a, mut b) = get!(usize, usize);

    let mut ans = vec![vec![false; 100]; 100];

    let mut i = 0;
    let mut j = 0;
    while a > 1 {
        ans[i][j] = true;
        // debug!(i, j);
        j += 2;
        if j >= 100 {
            j = 0;
            i += 2;
        }
        a -= 1;
    }

    for w in i + 2..100 {
        for k in 0..100 {
            ans[w][k] = true;
        }
    }
    j = 0;
    i += 3;
    while b > 1 {
        ans[i][j] = false;
        j += 2;
        if j >= 100 {
            j = 0;
            i += 2;
        }
        b -= 1;
    }

    util::with_bufwriter(|mut out| {
        writeln!(out, "100 100").unwrap();
        for v in ans {
            writeln!(
                out,
                "{}",
                v.iter()
                    .map(|&x| if x { '.' } else { '#' })
                    .collect::<String>()
            ).unwrap();
        }
    });
}

