use std::cmp;
use std::collections::{HashMap, HashSet, BTreeMap, BTreeSet};
fn main() {
    input! {
        A: usize,
        B: usize,
    }

    let K = 50;
    let mut grid = vec![vec![false; 2*K]; 2*K];
    for row in 0..K {
        for col in 0..2*K {
            grid[row][col] = true;
        }
    }

    'outer: for row in 1..K {
        for col in 1..2*K-1 {
            if A-1 == 0 {
                break 'outer;
            } else if grid[row-1][col-1] && grid[row-1][col] && grid[row][col-1] && 
                grid[row+1][col+1] && grid[row+1][col] && grid[row][col+1] &&
                    grid[row+1][col-1] && grid[row-1][col-1] {
                grid[row][col] = false;
                A -= 1;
            }
        }
    }

    'outer: for row in K+1..2*K-1 {
        for col in 1..2*K-1 {
            if B-1 == 0 {
                break 'outer;
            } else if !(grid[row-1][col-1] || grid[row-1][col] || grid[row][col-1] ||
                        grid[row+1][col+1] || grid[row+1][col] || grid[row][col+1] ||
                        grid[row+1][col-1] || grid[row-1][col+1]) {
                grid[row][col] = true;;
                B -= 1;
            }
        }
    }

    println!("100 100");
    for row in 0..2*K {
        for col in 0..2*K {
            if grid[row][col] {
                print!("#");
            } else {
                print!(".");
            }
        }
        print!("\n");
    }
}

