        (t[0], t[1])
    };

    let mut bd: Vec<Vec<char>> = vec![vec!['.'; 100]; 100];

    for y in 0..bd.len() {
        for x in 0..bd[y].len() {
            bd[y][x] = if y < bd.len() / 2 { '.' } else { '#' };
        }
    }

    for i in 0..a - 1 {
        let x = i % 49;
        let y = i / 49;
        bd[51 + y * 2][1 + x * 2] = '.';
    }

    for i in 0..b - 1 {
        let x = i % 49;
        let y = i / 49;
        bd[1 + y * 2][1 + x * 2] = '#';
    }

    for row in bd.iter() {
        for c in row.iter() {
            print!("{}", c);
        }
        println!();
    }
}

