const DX: [usize; 4] = [1, 0, std::usize::MAX, 0];
const DY: [usize; 4] = [0, 1, 0, std::usize::MAX];
const H: usize = 100;
const W: usize = 100;
fn solve<R: std::io::Read, W: std::io::Write>(io: &mut IO<R, W>) {
    let (mut a, mut b): (usize, usize) = io.read();

    let white = if a < b { '.' } else { '#' };
    let black = if a < b { '#' } else { '.' };
    if a < b {
        std::mem::swap(&mut a, &mut b);
    }

    debug_assert!(a >= b);
    b -= 1;
    let mut m: Vec<Vec<char>> = vec![vec![black;W];H];
    for i in 0..H / 4 {
        for j in 0..W / 4 {
            if a == 0 && b == 0 {
                continue;
            }
            for ii in 4 * i..4 * i + 3 {
                for jj in 4 * j..4 * j + 3 {
                    m[ii][jj] = white;
                }
            }
            a -= 1;
            if b > 0 {
                m[4 * i + 1][4 * j + 1] = black;
                b -= 1;
            }
        }
    }



    for i in 0..H {
        io.writesln(&m[i], "");
    }
}

